# Home is a full visual landing/dashboard. The artwork contains the reference
# sidebar itself, so Streamlit's native sidebar is hidden only on Home.
CURRENT_PAGE_KEY = str(st.query_params.get("page", "home")).lower()

ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data'
FILES={k:DATA/f for k,f in {'bagger':'bagger_scores.json','fund':'fundamentals.json','momentum':'momentum_scores.json','risk':'risk_metrics.json','profile':'company_profiles.json','daily':'daily_cache.json','journal_report_cache':'journal_report_cache.json'}.items()}
ENRICHMENT_FILE = DATA / 'company_enrichment.json'

LOCAL_PEER_GROUPS_FILE = DATA / 'local_peer_groups.json'
def load_local_peer_groups():
    try:
        payload = json.loads(LOCAL_PEER_GROUPS_FILE.read_text(encoding='utf-8'))
        groups = payload.get('groups', {})
        return groups if isinstance(groups, dict) else {}
    except Exception:
        return {}

LOCAL_PEER_GROUPS = load_local_peer_groups()
def get_local_peer_group(symbol):
    key = str(symbol or '').upper().strip()
    if key and not key.endswith('.JK'):
        key += '.JK'
    group = LOCAL_PEER_GROUPS.get(key, {})
    return group if isinstance(group, dict) else {}

# RowletAI mascot asset. Falls back to a small CSS owl if the image is unavailable.
MASCOT_FILE = ROOT / "assets" / "rowlet_ai_mascot.png"
HERO_VISUAL_FILE = ROOT / "assets" / "rowletai_hero_visual.png"
COMPARE_INSIGHT_BANNER_FILES = [ROOT / "assets" / "compare_insight_banner(1).png", ROOT / "assets" / "compare_insight_banner.png"]
METHODOLOGY_BANNER_FILES = [ROOT / "assets" / "methodology.png", ROOT / "app" / "assets" / "methodology.png"]

def mascot_data_uri():
    try:
        raw = MASCOT_FILE.read_bytes()
        return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
    except Exception:
        return ""

def hero_visual_uri():
    try:
        raw = HERO_VISUAL_FILE.read_bytes()
        return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
    except Exception:
        return ""
def sidebar_asset_uri(filename):
    try:
        raw = (ROOT / "assets" / filename).read_bytes()
        return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
    except Exception:
        return ""

def compare_insight_banner_uri():
    for path in COMPARE_INSIGHT_BANNER_FILES:
        try:
            raw = path.read_bytes()
            return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
        except Exception:
            continue
    return ""

def methodology_banner_uri():
    for path in METHODOLOGY_BANNER_FILES:
        try:
            raw = path.read_bytes()
            return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
        except Exception:
            continue
    return ""

SECTORS_APP_ICON_FILES = [ROOT / "assets" / "sectors_app.png", ROOT / "app" / "assets" / "sectors_app.png"]
def sectors_app_icon_uri():
    for path in SECTORS_APP_ICON_FILES:
        try:
            raw = path.read_bytes()
            return "data:image/png;base64," + base64.b64encode(raw).decode("ascii")
        except Exception:
            continue
    return ""


