@st.cache_data(ttl=900, show_spinner=False)
def _load_json_cached(path, mtime_ns, file_size):
    # File metadata participates in the cache key; changed source files refresh immediately.
    with open(path,'r',encoding='utf-8') as f:
        return json.load(f)

def load(path):
    resolved=Path(path).resolve()
    stat=resolved.stat()
    return _load_json_cached(str(resolved),stat.st_mtime_ns,stat.st_size)
def ddf(x):
    if not isinstance(x,dict):return pd.DataFrame(x)
    return pd.DataFrame([{**(v if isinstance(v,dict) else {}),'symbol':k} for k,v in x.items()])
def clean(x):
    x=x.copy(); x.columns=[str(c) for c in x.columns]
    if 'symbol' in x:x['symbol']=x['symbol'].astype(str).str.upper().str.strip()
    return x.loc[:,~x.columns.duplicated()]
def n(x):
    try:return float(x)
    except:return np.nan
def pct(x):
    # Fundamentals and return fields are stored as decimal ratios (0.197 = 19.7%).
    x=n(x)
    if np.isnan(x):return '—'
    x*=100
    return f'{x:.2f}%' if 0<abs(x)<1 else f'{x:.1f}%'
def money(x):
    x=n(x)
    if np.isnan(x):return '—'
    if x>=1e12:return f'Rp {x/1e12:.2f}T'
    if x>=1e9:return f'Rp {x/1e9:.2f}B'
    return f'Rp {x:,.0f}'

def escape_html(value):
    """Escape dynamic text before placing it inside raw HTML markup."""
    return html_lib.escape(str(value if value is not None else ''),quote=True)

def safe_http_url(value):
    """Allow only absolute HTTP(S) URLs in dynamic HTML attributes."""
    candidate=str(value or '').strip()
    try:
        parts=urlsplit(candidate)
        return candidate if parts.scheme.lower() in ('http','https') and parts.netloc else ''
    except Exception:
        return ''

def safe_image_src(value):
    """Allow HTTP(S) image URLs and validated raster image data URLs.

    Company Journal downloads provider images server-side and embeds them as
    data URLs. Keep that browser-safe path while rejecting SVG and malformed
    payloads so fetched data cannot inject active markup into the page.
    """
    candidate=str(value or '').strip()
    if candidate.lower().startswith('data:'):
        try:
            header, payload = candidate.split(',', 1)
            allowed_headers = {
                'data:image/jpeg;base64',
                'data:image/jpg;base64',
                'data:image/png;base64',
                'data:image/webp;base64',
                'data:image/gif;base64',
                'data:image/avif;base64',
            }
            if (header.lower() in allowed_headers
                    and 0 < len(payload) <= 11_000_000
                    and re.fullmatch(r'[A-Za-z0-9+/]+={0,2}', payload)):
                return candidate
        except Exception:
            pass
        return ''
    return safe_http_url(candidate)

# MARKET INTELLIGENCE STEP 2 — SECTOR FILTER DATA SOURCE
# Sector membership must not depend on company_profiles.json because
# that local file may have blank sector values. Use Sectors API v2
# Companies/Screener endpoint on demand, then intersect with the
# existing Bagger universe. No scoring methodology is changed.
# ================================================================
MI_SECTORS_CANONICAL = [
    "Basic Materials",
    "Consumer Cyclicals",
    "Consumer Defensive",
    "Energy",
    "Financials",
    "Healthcare",
    "Industrials",
    "Real Estate",
    "Technology",
    "Telecommunications",
    "Utilities",
]


def mi_secret(name):
    """Read a secret from environment first, then local .env files.
    Never print or expose the secret.
    """
    value=os.getenv(name)
    if value:
        return value.strip().strip('"').strip("'")
    candidates=[ROOT/'.env', ROOT.parent/'.env']
    for env_path in candidates:
        try:
            if not env_path.exists():
                continue
            for raw in env_path.read_text(encoding='utf-8').splitlines():
                line=raw.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                key,val=line.split('=',1)
                if key.strip()==name:
                    return val.strip().strip('"').strip("'")
        except Exception:
            continue
    return ""


@st.cache_data(ttl=600, show_spinner=False)
def mi_sectors_api_request(url, token):
    """Cache Sectors v2 responses and avoid retrying transient network failures."""
    headers_list=[
        {'Authorization':str(token),'User-Agent':'RowletAI/MarketIntelligence'},
        {'Authorization':f'Bearer {token}','User-Agent':'RowletAI/MarketIntelligence'},
        {'X-API-Key':str(token),'User-Agent':'RowletAI/MarketIntelligence'},
    ]
    for headers in headers_list:
        try:
            req=Request(url,headers=headers,method='GET')
            with urlopen(req,timeout=8) as response:
                return json.loads(response.read().decode('utf-8'))
        except HTTPError as exc:
            if exc.code in (401,403):
                continue
            return None
        except Exception:
            return None
    return None


def mi_extract_symbols(payload):
    """Extract symbols from the flexible v2 screener response shape."""
    if isinstance(payload,list):
        items=payload
    elif isinstance(payload,dict):
        items=payload.get('results')
        if items is None: items=payload.get('data')
        if items is None: items=payload.get('companies')
        if items is None: items=[]
    else:
        items=[]
    symbols=[]
    for item in items:
        if isinstance(item,str):
            sym=item
        elif isinstance(item,dict):
            sym=item.get('symbol') or item.get('ticker') or item.get('code')
        else:
            sym=None
        if sym:
            sym=str(sym).upper().strip()
            if not sym.endswith('.JK'):
                sym += '.JK'
            symbols.append(sym)
    return sorted(set(symbols))


@st.cache_data(ttl=3600, show_spinner=False)
def mi_extract_company_rows(payload):
    """Extract company records from flexible Sectors v2 response shapes."""
    if isinstance(payload, list):
        return [x for x in payload if isinstance(x, dict)]
    if not isinstance(payload, dict):
        return []
    # Common top-level containers.
    for key in ('results','data','companies','items'):
        value=payload.get(key)
        if isinstance(value,list):
            return [x for x in value if isinstance(x,dict)]
        if isinstance(value,dict):
            rows=mi_extract_company_rows(value)
            if rows:
                return rows
    # Last-resort recursive scan for a list of company-like dicts.
    for value in payload.values():
        if isinstance(value,list) and value and all(isinstance(x,dict) for x in value):
            if any(('symbol' in x or 'ticker' in x or 'code' in x) for x in value):
                return value
        if isinstance(value,dict):
            rows=mi_extract_company_rows(value)
            if rows:
                return rows
    return []


def mi_normalize_sector(value):
    return str(value or '').strip().casefold().replace('_','-').replace(' ','-')

MI_SECTOR_SLUGS={
    'Basic Materials':'basic-materials',
    'Consumer Cyclicals':'consumer-cyclicals',
    'Consumer Defensive':'consumer-defensive',
    'Energy':'energy',
    'Financials':'financials',
    'Healthcare':'healthcare',
    'Industrials':'industrials',
    'Real Estate':'real-estate',
    'Technology':'technology',
    'Telecommunications':'telecommunications',
    'Utilities':'utilities',
}


def _mi_sectors_token():
    return (mi_secret('SECTORS_API_KEY') or mi_secret('SECTORS_API_TOKEN')
            or mi_secret('SECTORS_TOKEN') or mi_secret('SECTORS_API'))


def _mi_sectors_token_fingerprint(token):
    return hashlib.sha256(str(token).encode('utf-8')).hexdigest()


@st.cache_data(ttl=3600, show_spinner=False)
def _mi_company_sector_map_cached(token_fingerprint):
    """Cache sector membership for one hour, keyed by a non-reversible API-key fingerprint."""
    token = _mi_sectors_token()
    if not token or _mi_sectors_token_fingerprint(token) != token_fingerprint:
        return {}
    mapping = {}
    for offset in range(0, 1000, 200):
        params = urlencode({'limit': 200, 'offset': offset, 'include_query_values': 'true'})
        payload = mi_sectors_api_request(f'https://api.sectors.app/v2/companies/?{params}', token)
        rows = mi_extract_company_rows(payload)
        if not rows:
            break
        for item in rows:
            sym = item.get('symbol') or item.get('ticker') or item.get('code')
            sector = item.get('sector') or item.get('sector_name') or item.get('sectorName')
            if sym and sector:
                sym = str(sym).upper().strip()
                if not sym.endswith('.JK'):
                    sym += '.JK'
                mapping[sym] = str(sector).strip()
        if len(rows) < 200:
            break
    return mapping


def mi_company_sector_map():
    """Return cached Sectors v2 company-to-sector membership."""
    token = _mi_sectors_token()
    if not token:
        return {}
    return _mi_company_sector_map_cached(_mi_sectors_token_fingerprint(token))


@st.cache_data(ttl=3600, show_spinner=False)
def _mi_sector_symbols_cached(sector, slug, token_fingerprint):
    """Cache a sector lookup for one hour without tying it to a raw API secret."""
    token = _mi_sectors_token()
    if not token or _mi_sectors_token_fingerprint(token) != token_fingerprint:
        return []
    symbols = []
    for offset in range(0, 1000, 200):
        where = f"sector='{slug}'"
        params = urlencode({'where': where, 'limit': 200, 'offset': offset, 'include_query_values': 'true'})
        payload = mi_sectors_api_request(f'https://api.sectors.app/v2/companies/?{params}', token)
        rows = mi_extract_company_rows(payload)
        if not rows:
            break
        for item in rows:
            sym = item.get('symbol') or item.get('ticker') or item.get('code')
            if not sym:
                continue
            sym = str(sym).upper().strip()
            if not sym.endswith('.JK'):
                sym += '.JK'
            row_sector = item.get('sector') or item.get('sector_name') or item.get('sectorName')
            if row_sector is None or mi_normalize_sector(row_sector) == mi_normalize_sector(slug):
                symbols.append(sym)
        if len(rows) < 200:
            break
    if symbols:
        return sorted(set(symbols))
    mapping = mi_company_sector_map()
    target = mi_normalize_sector(slug)
    return sorted({sym for sym, value in mapping.items() if mi_normalize_sector(value) == target})


def mi_sector_symbols(selected_sector):
    """Resolve a sector to IDX symbols using a one-hour cached Sectors lookup."""
    sector = str(selected_sector or '').strip()
    if not sector or sector == 'ALL SECTORS':
        return []
    token = _mi_sectors_token()
    if not token:
        return []
    slug = MI_SECTOR_SLUGS.get(sector, mi_normalize_sector(sector))
    return _mi_sector_symbols_cached(sector, slug, _mi_sectors_token_fingerprint(token))


def mi_sector_filter_symbols(df, selected_sector):
    """Resolve selected sector to symbols, with local-data fallback."""
    if selected_sector == 'ALL SECTORS':
        return None
    api_symbols=set(mi_sector_symbols(selected_sector))
    if api_symbols:
        return api_symbols
    if 'sector' in df.columns:
        local=df['sector'].astype(str).str.strip().str.casefold()
        return set(df.loc[local.eq(str(selected_sector).strip().casefold()), 'symbol'].astype(str).str.upper())
    return set()


def _journal_report_symbol(symbol):
    sym=str(symbol or '').upper().strip()
    return sym if sym.endswith('.JK') else f'{sym}.JK'


def load_journal_report_cache():
    path=FILES['journal_report_cache']
    if not path.exists():
        return {}
    try:
        with open(path,'r',encoding='utf-8') as f:
            payload=json.load(f)
        return payload if isinstance(payload,dict) else {}
    except Exception:
        return {}


def save_journal_report_cache(cache):
    path=FILES['journal_report_cache']
    path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_suffix('.tmp')
    with open(tmp,'w',encoding='utf-8') as f:
        json.dump(cache,f,ensure_ascii=False,indent=2)
    tmp.replace(path)


def normalize_sectors_company_report(payload):
    """Normalize the Sectors v2 Company Report without inventing values."""
    if not isinstance(payload,dict):
        return {}
    overview=payload.get('overview') if isinstance(payload.get('overview'),dict) else {}
    valuation=payload.get('valuation') if isinstance(payload.get('valuation'),dict) else {}
    future=payload.get('future') if isinstance(payload.get('future'),dict) else {}
    financials=payload.get('financials') if isinstance(payload.get('financials'),dict) else {}
    dividend=payload.get('dividend') if isinstance(payload.get('dividend'),dict) else {}
    return {
        'symbol':payload.get('symbol') or overview.get('symbol'),
        'company_name':payload.get('company_name') or overview.get('company_name'),
        'sector':overview.get('sector'),
        'industry':overview.get('industry'),
        'sub_industry':overview.get('sub_industry') or overview.get('subindustry'),
        'market_cap':overview.get('market_cap'),
        'last_close_price':overview.get('last_close_price') or overview.get('price') or overview.get('close'),
        'latest_close_date':overview.get('latest_close_date') or overview.get('date'),
        'historical_financials':financials.get('historical_financials') or [],
        'historical_eps':financials.get('historical_eps') or [],
        'company_growth_forecasts':future.get('company_growth_forecasts') or [],
        'dividend':dividend,
        'valuation':valuation,
        'management':payload.get('management') or {},
        'ownership':payload.get('ownership') or {},
        'peers':payload.get('peers') or {},
        'tags':overview.get('tags') or [],
        'indices':overview.get('indices') or [],
    }


def fetch_sectors_company_report(symbol, force=False):
    """Fetch a Company Report, retain stale data, and expose safe status metadata."""
    from datetime import datetime, timezone, timedelta
    sym=_journal_report_symbol(symbol)
    cache=load_journal_report_cache()
    cached_entry=cache.get(sym) if isinstance(cache.get(sym),dict) else {}
    cached_report=cached_entry.get('report') if isinstance(cached_entry.get('report'),dict) else None
    def parse_stamp(value):
        try:
            stamp=datetime.fromisoformat(str(value or '').replace('Z','+00:00'))
            return stamp.replace(tzinfo=timezone.utc) if stamp.tzinfo is None else stamp
        except Exception:
            return None
    fetched_at=parse_stamp(cached_entry.get('fetched_at'))
    checked_at=parse_stamp(cached_entry.get('checked_at'))
    now=datetime.now(timezone.utc)
    if not force and cached_report and fetched_at and now-fetched_at<timedelta(hours=24):
        st.session_state['_journal_company_report_status']={'status':'cached','checked_at':cached_entry.get('checked_at') or cached_entry.get('fetched_at') or ''}
        return cached_report
    if force and cached_entry.get('api_status')=='rate_limited' and checked_at and now-checked_at<timedelta(minutes=1):
        st.session_state['_journal_company_report_status']={'status':'rate_limited','checked_at':cached_entry.get('checked_at') or ''}
        return cached_report

    if not force and checked_at and now-checked_at<timedelta(hours=6):
        st.session_state['_journal_company_report_status']={'status':cached_entry.get('api_status') or 'recently_checked','checked_at':cached_entry.get('checked_at') or ''}
        return cached_report
    token=(journal_secret('SECTORS_API_KEY') or journal_secret('SECTORS_API_TOKEN') or journal_secret('SECTORS_TOKEN') or journal_secret('SECTORS_API'))
    if not token:
        st.session_state['_journal_company_report_status']={'status':'missing_api_key','checked_at':''}
        return cached_report
    url=f"https://api.sectors.app/v2/company/report/{quote(sym,safe='')}/"
    headers_list=[
        {'Authorization':str(token),'User-Agent':'RowletAI/2.0'},
        {'Authorization':f'Bearer {token}','User-Agent':'RowletAI/2.0'},
        {'X-API-Key':str(token),'User-Agent':'RowletAI/2.0'},
    ]
    payload=None
    last_status='network_error'
    for headers in headers_list:
        try:
            req=Request(url,headers=headers)
            with urlopen(req,timeout=8) as response:
                candidate=json.loads(response.read().decode('utf-8'))
            if isinstance(candidate,dict) and candidate:
                payload=candidate
                last_status='ok'
                break
            last_status='empty_response'
            break
        except HTTPError as exc:
            if exc.code in (401,403):
                last_status='authentication_failed'
                continue
            if exc.code==429:
                last_status='rate_limited'
            elif exc.code==404:
                last_status='symbol_not_found'
            else:
                last_status=f'http_{exc.code}'
            break
        except Exception:
            last_status='network_or_invalid_response'
            break
    checked_now=datetime.now(timezone.utc).isoformat()
    if not isinstance(payload,dict):
        cache[sym]={**cached_entry,'checked_at':checked_now,'api_status':last_status}
        save_journal_report_cache(cache)
        st.session_state['_journal_company_report_status']={'status':last_status,'checked_at':checked_now}
        return cached_report
    report=normalize_sectors_company_report(payload)
    if not report:
        cache[sym]={**cached_entry,'checked_at':checked_now,'api_status':'empty_response'}
        save_journal_report_cache(cache)
        st.session_state['_journal_company_report_status']={'status':'empty_response','checked_at':checked_now}
        return cached_report
    cache[sym]={
        'source':'Sectors API v2 Company Report',
        'fetched_at':checked_now,
        'checked_at':checked_now,
        'api_status':'ok',
        'report':report,
        'raw':payload,
    }
    save_journal_report_cache(cache)
    st.session_state['_journal_company_report_status']={'status':'ok','checked_at':checked_now}
    return report


def journal_report_for_symbol(symbol, force=False):
    return fetch_sectors_company_report(symbol, force=force)


def journal_apply_report_context(row, report):
    """Enrich Journal display fields from the verified Company Report only.

    This is Journal presentation data; it does not modify Bagger scoring inputs.
    Existing local values remain the fallback when the Company Report is missing.
    """
    out=dict(row)
    if not isinstance(report,dict):
        return out
    def fill(key, value):
        if value is not None and value != '' and (key not in out or pd.isna(out.get(key)) or out.get(key) in ('',None)):
            out[key]=value
    fill('company_name', report.get('company_name'))
    fill('market_cap', report.get('market_cap'))
    fill('sector', report.get('sector'))
    fill('industry', report.get('industry'))
    val=report.get('valuation') if isinstance(report.get('valuation'),dict) else {}
    div=report.get('dividend') if isinstance(report.get('dividend'),dict) else {}
    fill('pe_ttm', val.get('pe_ttm'))
    fill('pb_mrq', val.get('pb_mrq'))
    fill('forward_pe', val.get('forward_pe'))
    fill('intrinsic_value', val.get('intrinsic_value'))
    fill('dividend_ttm', div.get('dividend_ttm'))
    fill('yield_ttm', div.get('yield_ttm'))
    fill('payout_ratio', div.get('payout_ratio'))
    fill('cash_payout_ratio', div.get('cash_payout_ratio'))
    fill('last_ex_dividend_date', div.get('last_ex_dividend_date'))
    fill('historical_dividends', div.get('historical_dividends'))
    return out

def _dataset_signature():
    signature=[]
    for key in ('bagger','fund','momentum','risk','profile'):
        path=Path(FILES[key]).resolve()
        try:
            stat=path.stat()
            signature.append((str(path),stat.st_mtime_ns,stat.st_size))
        except OSError:
            signature.append((str(path),None,None))
    return tuple(signature)

@st.cache_data(ttl=900, show_spinner=False)
def _dataset_cached(signature):
    # The signature is included in the cache key so data file changes invalidate this result.
    b=clean(pd.DataFrame(load(FILES['bagger']))); f=clean(pd.DataFrame(load(FILES['fund']))); m=clean(ddf(load(FILES['momentum']))); r=clean(ddf(load(FILES['risk']))); p=clean(pd.DataFrame(load(FILES['profile'])))
    fc=[c for c in ['symbol','company_name','market_cap','roe_ttm','roa_ttm','der_mrq','pe_ttm','pb_mrq','yield_ttm','dividend_ttm','yoy_quarter_revenue_growth','yoy_quarter_earnings_growth'] if c in f]
    b=b.merge(f[fc],on='symbol',how='left',suffixes=('','_fund'))
    mc=[c for c in ['symbol','return_20d','return_60d','ma20','ma60','price_vs_ma20','price_vs_ma60','liquidity_flag'] if c in m]
    if mc:b=b.merge(m[mc],on='symbol',how='left',suffixes=('','_mom'))
    rc=[c for c in ['symbol','volatility_20d','volatility_60d','max_drawdown_60d','max_daily_loss_20d'] if c in r]
    if rc:b=b.merge(r[rc],on='symbol',how='left',suffixes=('','_risk'))
    pc=[c for c in ['symbol','description','sector','industry'] if c in p]
    if pc:b=b.merge(p[pc],on='symbol',how='left')
    b=b.loc[:,~b.columns.duplicated()]
    if 'company_name' not in b:b['company_name']=b['symbol']
    return b,m,r,p

def dataset():
    return _dataset_cached(_dataset_signature())
try:
    df,momentum,risk,profiles=dataset()
except Exception:
    logging.getLogger(__name__).exception('Unable to load RowletAI source data')
    st.error('Data RowletAI belum dapat dimuat. Periksa file sumber JSON atau hubungi admin.')
    st.stop()

def kpi(label,value,note=''):
    st.markdown(f'<div class="kpi"><div class="kl">{label}</div><div class="kv">{value}</div><div class="kn">{note}</div></div>',unsafe_allow_html=True)
def section(t,d=''):
    st.markdown(f'<div class="section"><div class="title">{t}</div><div class="desc">{d}</div></div>',unsafe_allow_html=True)
def factor(name, score, desc, display=None):
    s = n(score)
    if display is not None:
        value_text = display
    elif np.isnan(s):
        value_text = "N/A"
    else:
        value_text = f"{s:.1f}"
    st.markdown(
        f'<div class="factor"><div class="fn">{name}</div><div class="fs">{value_text}</div><div class="fd">{desc}</div></div>',
        unsafe_allow_html=True
    )
def percentile_score(series, value, higher_is_better=True):
    """Universe-relative percentile score (0-100), used only for assessment display."""
    s = pd.to_numeric(series, errors="coerce").dropna()
    v = n(value)
    if np.isnan(v) or len(s) < 5:
        return np.nan
    rank = float((s <= v).mean() * 100.0)
    if not higher_is_better:
        rank = 100.0 - float((s <= v).mean() * 100.0) + (100.0 / max(len(s), 1))
    return float(np.clip(rank, 0, 100))

def _dividend_payout_quality_score(value):
    """Score payout ratio on sustainability, 0-100.

    The preferred zone is 30-60%. Very low payout is not penalized heavily,
    while payout above 100% is treated as materially weak evidence.
    """
    v=n(value)
    if not np.isfinite(v) or v < 0:
        return np.nan
    if v <= 0.30:
        return float(70 + (v/0.30)*15)
    if v <= 0.60:
        return float(85 + ((v-0.30)/0.30)*15)
    if v <= 0.75:
        return float(100 - ((v-0.60)/0.15)*20)
    if v <= 1.00:
        return float(80 - ((v-0.75)/0.25)*50)
    return float(max(10, 30 - min((v-1.00)/1.00*20, 20)))


def _dividend_cashflow_score(value):
    """Score cash payout coverage on sustainability, 0-100."""
    v=n(value)
    if not np.isfinite(v) or v < 0:
        return np.nan
    # Lower cash payout means more cash-flow headroom.
    if v <= 0.30:
        return 100.0
    if v <= 0.50:
        return float(100 - ((v-0.30)/0.20)*15)
    if v <= 0.70:
        return float(85 - ((v-0.50)/0.20)*25)
    if v <= 1.00:
        return float(60 - ((v-0.70)/0.30)*40)
    return float(max(5, 20 - min((v-1.00)*15, 15)))


def _dividend_consistency_score(history):
    """Score historical dividend consistency when verified history is present.

    Returns N/A when the source does not expose enough history. No missing
    years are inferred and no zero dividends are fabricated.
    """
    if not isinstance(history, (list, tuple, dict)):
        return np.nan
    entries=[]
    if isinstance(history, dict):
        iterable=[]
        for year, value in history.items():
            if isinstance(value, dict):
                item=dict(value); item.setdefault('year', year); iterable.append(item)
            else:
                iterable.append({'year':year, 'total_dividend':value})
    else:
        iterable=list(history)
    for item in iterable:
        if not isinstance(item, dict):
            continue
        d=n(item.get('total_dividend'))
        if not np.isfinite(d):
            d=n(item.get('dividend'))
        if not np.isfinite(d):
            d=n(item.get('dividend_per_share'))
        if np.isfinite(d):
            entries.append((item.get('year'), float(d)))
    if len(entries) < 3:
        return np.nan
    entries=sorted(entries, key=lambda x: str(x[0]))
    vals=[v for _,v in entries]
    positive=sum(v > 0 for v in vals)
    consistency=positive/len(vals)
    if len(vals) >= 5:
        base=100*consistency
    else:
        base=90*consistency
    # Reward a mostly stable/increasing series, but avoid making growth alone
    # dominate the dividend-quality score.
    changes=[]
    for a,b in zip(vals[:-1], vals[1:]):
        if a > 0:
            changes.append((b-a)/a)
    if changes:
        non_negative=sum(c >= -0.05 for c in changes)/len(changes)
        base=0.75*base + 0.25*(100*non_negative)
    return float(np.clip(base, 0, 100))


def dividend_score_engine(row, universe_df=None):
    """Dividend Quality Score (0-100) from verified evidence only.

    Components:
      - Yield attractiveness: 30%
      - Earnings payout sustainability: 25%
      - Cash-flow coverage: 25% (omitted when methodology is not applicable,
        such as banks, or when the source is missing)
      - Dividend consistency: 20% when verified historical dividend history exists

    Missing components are removed and the remaining weights are renormalized.
    Therefore an unavailable input never becomes a false zero.
    """
    r=row if isinstance(row, dict) else row.to_dict()
    components=[]
    details={}

    y=n(r.get('yield_ttm'))
    if np.isfinite(y) and universe_df is not None and 'yield_ttm' in universe_df:
        ys=pd.to_numeric(universe_df['yield_ttm'], errors='coerce').dropna()
        # Yield is evidence, not an instruction. Use the universe percentile
        # so the score is comparable across companies and periods.
        yscore=percentile_score(universe_df['yield_ttm'], y, True)
        if np.isfinite(yscore):
            components.append(('yield', yscore, 0.30)); details['yield_score']=float(yscore)
    else:
        yscore=np.nan
    if not np.isfinite(y):
        details['yield_score']=np.nan

    payout=n(r.get('payout_ratio'))
    pscore=_dividend_payout_quality_score(payout)
    if np.isfinite(pscore):
        components.append(('payout', pscore, 0.25)); details['payout_score']=float(pscore)
    else:
        details['payout_score']=np.nan

    sector=str(r.get('sector','')).lower(); industry=str(r.get('industry','')).lower()
    is_bank=('bank' in sector or 'bank' in industry)
    cash_payout=n(r.get('cash_payout_ratio'))
    cscore=_dividend_cashflow_score(cash_payout)
    if not is_bank and np.isfinite(cscore):
        components.append(('cashflow', cscore, 0.25)); details['cashflow_score']=float(cscore)
    else:
        details['cashflow_score']=np.nan
        details['cashflow_applicable']=not is_bank

    hscore=_dividend_consistency_score(r.get('historical_dividends'))
    if np.isfinite(hscore):
        components.append(('consistency', hscore, 0.20)); details['consistency_score']=float(hscore)
    else:
        details['consistency_score']=np.nan

    total_weight=sum(w for _,_,w in components)
    if total_weight <= 0:
        score=np.nan
    else:
        score=sum(v*w for _,v,w in components)/total_weight
        score=float(np.clip(score,0,100))

    details['score']=score
    details['coverage']=total_weight
    details['components_available']=len(components)
    details['status']='MEASURED' if np.isfinite(score) else 'INSUFFICIENT EVIDENCE'
    return details


def assessment_score(row, factor_name):
    """Research assessment layer.

    These six factors are deliberately separate from the five quantitative
    Bagger Score dimensions. They do NOT feed the composite score.

    Where the current dataset cannot support a defensible assessment,
    the UI shows N/A rather than inventing a number.
    """
    if factor_name == "Financial Strength":
        vals = []
        for key in ["roe_ttm", "roa_ttm"]:
            if key in df:
                v = percentile_score(df[key], row.get(key), True)
                if not np.isnan(v):
                    vals.append(v)
        if "der_mrq" in df:
            v = percentile_score(df["der_mrq"], row.get("der_mrq"), False)
            if not np.isnan(v):
                vals.append(v)
        return float(np.mean(vals)) if vals else np.nan

    if factor_name == "Growth":
        vals = []
        for key in ["yoy_quarter_revenue_growth", "yoy_quarter_earnings_growth"]:
            if key in df:
                v = percentile_score(df[key], row.get(key), True)
                if not np.isnan(v):
                    vals.append(v)
        return float(np.mean(vals)) if vals else np.nan

    if factor_name == "Business Profile Coverage":
        checks = [
            bool(str(row.get("description", "")).strip()) if pd.notna(row.get("description")) else False,
            bool(str(row.get("sector", "")).strip()) if pd.notna(row.get("sector")) else False,
            bool(str(row.get("industry", "")).strip()) if pd.notna(row.get("industry")) else False,
        ]
        return float(round(sum(checks) / 3 * 100, 1)) if any(checks) else np.nan

    if factor_name == "Price Attractiveness":
        vals = []
        for key in ("pe_ttm", "pb_mrq"):
            selected_multiple=n(row.get(key))
            if key in df and np.isfinite(selected_multiple) and selected_multiple>0:
                peers=pd.to_numeric(df[key],errors="coerce").where(pd.to_numeric(df[key],errors="coerce")>0)
                v=percentile_score(peers,selected_multiple,False)
                if not np.isnan(v):
                    vals.append(v)
        return float(np.mean(vals)) if vals else np.nan

    if factor_name == "Management Quality":
        # Current project dataset does not contain defensible management,
        # governance, track-record or insider-alignment evidence.
        return np.nan

    if factor_name == "Dividend":
        vals = []
        if "yield_ttm" in df:
            v = percentile_score(df["yield_ttm"], row.get("yield_ttm"), True)
            if not np.isnan(v):
                vals.append(v)
        if "dividend_ttm" in df:
            # Presence/absence is useful evidence, but does not override yield.
            dv = n(row.get("dividend_ttm"))
            if np.isfinite(dv) and dv>0:
                vals.append(100.0)
        return float(np.mean(vals)) if vals else np.nan

    return np.nan


def assessment_status(score):
    s = n(score)
    if np.isnan(s):
        return "INSUFFICIENT EVIDENCE"
    if s >= 75:
        return "STRONG EVIDENCE"
    if s >= 50:
        return "MODERATE EVIDENCE"
    return "LIMITED EVIDENCE"


def assessment_description(name, row, score):
    status = assessment_status(score)

    descriptions = {
        "Financial Strength": (
            "Relative evidence from ROE, ROA and leverage available in "
            "Sectors data. It is separate from the Bagger Score."
        ),
        "Growth": (
            "Relative evidence from recent year-over-year revenue and "
            "earnings growth. It is shown independently for research context."
        ),
        "Business Profile Coverage": (
            "Evidence coverage across company description, sector and "
            "industry classification. This measures profile completeness, "
            "not business quality."
        ),
        "Price Attractiveness": (
            "Relative valuation evidence using PE and PB. Lower relative "
            "multiples receive higher descriptive scores."
        ),
        "Management Quality": (
            "The current dataset does not provide sufficient management, "
            "governance or track-record evidence; score intentionally withheld."
        ),
        "Dividend": (
            "Relative dividend evidence using yield and available dividend "
            "data. It does not imply a recommendation."
        ),
    }

    base = descriptions.get(name, "Assessment based on available evidence.")
    if "INSUFFICIENT" in status:
        return base + " Evidence is currently insufficient."
    return base + f" {status.title()}."


def render_assessment_factors(row):
    section(
        "6 Key Assessment Factors",
        "A research layer that adds company context without changing the Bagger Score.",
    )

    factors = [
        ("Financial Strength", "Profitability + leverage"),
        ("Growth", "Revenue + earnings growth"),
        ("Business Profile Coverage", "Profile evidence coverage"),
        ("Price Attractiveness", "PE + PB context"),
        ("Management Quality", "Management / governance evidence"),
        ("Dividend", "Yield + dividend evidence"),
    ]

    cols = st.columns(3, gap="medium")
    for col, (name, subtitle) in zip(cols, factors):
        score = assessment_score(row, name)
        value = "N/A" if np.isnan(score) else f"{score:.1f}"
        status = assessment_status(score)
        desc = assessment_description(name, row, score)

        with col:
            st.html(
                f"""
                <div class="assessment-card assessment-card-v2">
                    <div class="assessment-topline">
                        <div>
                            <div class="assessment-name">{name}</div>
                            <div class="assessment-subtitle">{subtitle}</div>
                        </div>
                        <div class="assessment-score">{value}</div>
                    </div>
                    <div class="assessment-bar">
                        <span style="width:{0 if np.isnan(score) else max(0,min(100,score)):.0f}%"></span>
                    </div>
                    <div class="assessment-status">{status}</div>
                    <div class="assessment-desc">{desc}</div>
                </div>
                """
            )

    st.html(
        """
        <div class="assessment-note assessment-note-v2">
          <div class="assessment-note-icon">✦</div>
          <div>
            <b>Two layers, one research experience.</b>
            <span>
              Quantitative Signals describe what the market data measures;
              Assessment Factors organize the available company evidence.
              Assessment scores never feed the Bagger Score, avoiding double counting.
            </span>
          </div>
        </div>
        """
    )

