                selected_symbol=st.selectbox("Company",choices,index=default_idx,format_func=lambda s:s.replace(".JK",""),key="mi3_company",label_visibility="collapsed") if choices else None
                row=df[df.symbol.eq(selected_symbol)].iloc[0] if selected_symbol and selected_symbol in df.symbol.values else None
                if row is not None:
                    score=n(row.get("bagger_score"));sig=str(row.get("composite_signal","N/A")).replace("_"," ").title();ev=str(row.get("evidence_level","N/A"));sector=str(row.get("sector","—"))
