def history(symbol):
    try:raw=load(FILES['daily'])
    except:return pd.DataFrame()
    data=raw.get(symbol) if isinstance(raw,dict) else None
    if data is None:return pd.DataFrame()
    if isinstance(data,dict):data=data.get('data',list(data.values()))
    h=pd.DataFrame(data)
    dc=next((x for x in ['date','datetime','timestamp'] if x in h),None);cc=next((x for x in ['close','Close'] if x in h),None)
    if not dc or not cc:return pd.DataFrame()
    h['date']=pd.to_datetime(h[dc],errors='coerce');h['close']=pd.to_numeric(h[cc],errors='coerce');h=h.dropna(subset=['date','close']).sort_values('date').tail(120);h['MA20']=h.close.rolling(20).mean();h['MA60']=h.close.rolling(60).mean();return h


def journal_save_daily_cache(cache):
    """Persist on-demand Sectors Daily data without touching scoring files."""
    try:
        DATA.mkdir(parents=True, exist_ok=True)
        tmp=FILES['daily'].with_suffix('.journal.tmp')
        tmp.write_text(json.dumps(cache, ensure_ascii=False), encoding='utf-8')
        tmp.replace(FILES['daily'])
    except Exception:
        pass


@st.cache_data(ttl=21600, show_spinner=False)
def journal_daily_api(symbol, days=90):
    """Fetch daily history and return rows with a user-displayable status."""
    sym=str(symbol or '').upper().strip()
    if not sym:
        return {"rows": [], "status": "invalid_symbol"}
    token=(journal_secret('SECTORS_API_KEY') or journal_secret('SECTORS_API_TOKEN') or
           journal_secret('SECTORS_TOKEN') or journal_secret('SECTORS_API'))
    if not token:
        return {"rows": [], "status": "missing_api_key"}
    api_symbol=sym[:-3] if sym.endswith('.JK') else sym
    from datetime import datetime, timedelta
    end_date=datetime.now().date()
    window_days=min(max(int(days),1),90)
    start_date=end_date-timedelta(days=window_days)
    base_url=f"https://api.sectors.app/v2/daily/{quote(api_symbol, safe='')}/"
    url=base_url+f"?start={start_date.isoformat()}&end={end_date.isoformat()}"
    headers_list=[
        {'Authorization':str(token),'User-Agent':'RowletAI/2.0'},
        {'Authorization':f'Bearer {token}','User-Agent':'RowletAI/2.0'},
        {'X-API-Key':str(token),'User-Agent':'RowletAI/2.0'},
    ]
    last_status="network_error"
    for headers in headers_list:
        try:
            req=Request(url,headers=headers)
            with urlopen(req,timeout=15) as response:
                payload=json.loads(response.read().decode('utf-8'))
            rows=payload.get('data') if isinstance(payload,dict) else payload
            if isinstance(rows,dict):
                rows=list(rows.values())
            clean_rows=[]
            if isinstance(rows,list):
                for item in rows:
                    if not isinstance(item,dict):
                        continue
                    close=n(item.get('close', item.get('Close')))
                    date=item.get('date', item.get('datetime', item.get('timestamp')))
                    if not np.isnan(close) and close>0 and date:
                        clean_rows.append({**item,'symbol':sym,'close':float(close),'date':str(date)})
            if clean_rows:
                return {"rows": clean_rows, "status": "ok"}
            last_status="empty_response"
        except HTTPError as exc:
            if exc.code in (401,403):
                last_status="authentication_failed"
                continue
            if exc.code==404:
                last_status="symbol_not_found"
                break
            else:
                last_status=f"http_error_{exc.code}"
        except Exception:
            last_status="network_or_invalid_response"
    return {"rows": [], "status": last_status}



def journal_daily_history(symbol, minimum_rows=61):
    """Refresh daily history and retain a compact diagnostic for the Journal UI."""
    from datetime import datetime, timezone, timedelta
    sym=str(symbol or '').upper().strip()
    try:
        cache=load(FILES['daily'])
    except Exception:
        cache={}
    if not isinstance(cache,dict):
        cache={}
    entry=cache.get(sym)
    metadata=entry if isinstance(entry,dict) else {}
    if isinstance(entry,dict):
        existing=entry.get('data')
        if not isinstance(existing,list):
            existing=list(entry.values())
    else:
        existing=entry
    existing=existing if isinstance(existing,list) else []
    def parse_stamp(value):
        try:
            stamp=datetime.fromisoformat(str(value or '').replace('Z','+00:00'))
            return stamp.replace(tzinfo=timezone.utc) if stamp.tzinfo is None else stamp
        except Exception:
            return None
    def frame(rows):
        h=pd.DataFrame(rows)
        if h.empty:
            return h
        dc=next((x for x in ['date','datetime','timestamp'] if x in h.columns),None)
        cc=next((x for x in ['close','Close'] if x in h.columns),None)
        if not dc or not cc:
            return pd.DataFrame()
        h['date']=pd.to_datetime(h[dc],errors='coerce')
        h['close']=pd.to_numeric(h[cc],errors='coerce')
        return h.dropna(subset=['date','close']).sort_values('date').drop_duplicates('date')
    now=datetime.now(timezone.utc)
    h=frame(existing)
    checked_at=parse_stamp(metadata.get('checked_at'))
    if checked_at is None:
        latest=None
        if not h.empty:
            try:
                latest=pd.Timestamp(h['date'].max()).to_pydatetime()
                if latest.tzinfo is None:
                    latest=latest.replace(tzinfo=timezone.utc)
            except Exception:
                latest=None
        checked_at=now-timedelta(hours=12) if latest is None or now-latest>timedelta(days=4) else now
    needs_refresh=len(h)<minimum_rows or now-checked_at>=timedelta(hours=6)
    if needs_refresh:
        api_result=journal_daily_api(sym)
        if isinstance(api_result,dict):
            fresh=api_result.get('rows') or []
            api_status=str(api_result.get('status') or 'unknown')
        else:
            fresh=api_result if isinstance(api_result,list) else []
            api_status='ok' if fresh else 'unknown'
        checked_now=datetime.now(timezone.utc).isoformat()
        if fresh:
            merged=frame(existing+fresh)
            if not merged.empty:
                records=merged.assign(date=merged['date'].dt.strftime('%Y-%m-%d')).to_dict('records')
                cache[sym]={'data':records,'fetched_at':checked_now,'checked_at':checked_now,'api_status':'ok'}
                journal_save_daily_cache(cache)
                h=merged
            else:
                cache[sym]={'data':existing,'fetched_at':metadata.get('fetched_at'),'checked_at':checked_now,'api_status':'empty_response'}
                journal_save_daily_cache(cache)
                api_status='empty_response'
        else:
            cache[sym]={'data':existing,'fetched_at':metadata.get('fetched_at'),'checked_at':checked_now,'api_status':api_status}
            journal_save_daily_cache(cache)
    current_entry=cache.get(sym) if isinstance(cache.get(sym),dict) else {}
    api_status=str(current_entry.get('api_status') or 'not_checked')
    if h.empty:
        display_status=api_status
    elif api_status not in {'ok','not_checked'}:
        display_status='stale_cache'
    elif len(h)<minimum_rows:
        display_status='partial_history'
    else:
        display_status='available'
    as_of=''
    if not h.empty:
        try:
            as_of=pd.Timestamp(h['date'].max()).strftime('%Y-%m-%d')
        except Exception:
            pass
    st.session_state['journal_daily_data_status']={
        'symbol':sym,'status':display_status,'api_status':api_status,'rows':int(len(h)),
        'minimum_rows':int(minimum_rows),'as_of':as_of,
        'checked_at':current_entry.get('checked_at') or metadata.get('checked_at') or '',
    }
    return h



def journal_daily_metrics(symbol):
    """Calculate transparent momentum/risk evidence from verified daily closes."""
    h=journal_daily_history(symbol, minimum_rows=61)
    if h.empty:
        return {}, h
    c=pd.to_numeric(h['close'],errors='coerce').dropna().reset_index(drop=True)
    out={}
    if len(c)>=21:
        out['return_20d']=float(c.iloc[-1]/c.iloc[-21]-1)
        ma20=float(c.tail(20).mean())
        out['ma20']=ma20
        out['price_vs_ma20']=float(c.iloc[-1]/ma20-1) if ma20 else np.nan
    if len(c)>=61:
        out['return_60d']=float(c.iloc[-1]/c.iloc[-61]-1)
        ma60=float(c.tail(60).mean())
        out['ma60']=ma60
        out['price_vs_ma60']=float(c.iloc[-1]/ma60-1) if ma60 else np.nan
    daily_ret=c.pct_change().dropna()
    if len(daily_ret)>=20:
        r20=daily_ret.tail(20)
        out['volatility_20d']=float(r20.std(ddof=1)*np.sqrt(252)) if len(r20)>1 else np.nan
        out['max_daily_gain_20d']=float(r20.max())
        out['max_daily_loss_20d']=float(r20.min())
        out['zero_return_ratio_20d']=float((r20.abs()<1e-12).mean())
        out['unique_price_ratio_20d']=float(c.tail(20).nunique()/20)
    if len(daily_ret)>=60:
        r60=daily_ret.tail(60)
        out['volatility_60d']=float(r60.std(ddof=1)*np.sqrt(252)) if len(r60)>1 else np.nan
        prices=c.tail(60)
        peak=prices.cummax()
        out['max_drawdown_60d']=float((prices/peak-1).min())
    return out,h



def journal_dynamic_scores(symbol, row, daily_metrics):
    """Derive Journal-only momentum/risk scores from verified daily evidence.

    This does not overwrite the frozen Market Intelligence JSON files. It uses
    the existing universe score distributions as the reference population and
    only produces scores when the required daily evidence is actually present.
    """
    if not daily_metrics:
        return {}
    out={}
    sym=str(symbol or '').upper().strip()

    # Momentum: four observable price signals, equal-weighted.  Existing
    # momentum_scores.json is used as the reference universe.
    try:
        md=load(FILES['momentum'])
        if isinstance(md,dict):
            mdf=pd.DataFrame(md.values())
        else:
            mdf=pd.DataFrame(md)
    except Exception:
        mdf=pd.DataFrame()
    mom_cols=['return_20d','return_60d','price_vs_ma20','price_vs_ma60']
    mom_vals=[]
    for c in mom_cols:
        v=n(daily_metrics.get(c))
        if np.isnan(v):
            continue
        if not mdf.empty and c in mdf.columns:
            ref=pd.to_numeric(mdf[c],errors='coerce').dropna()
            if len(ref)>=5:
                # Exclude the selected company from the reference population before ranking.
                ref_symbols=mdf.get("symbol",pd.Series(dtype=str)).astype(str).str.upper().str.strip()
                target_key=sym[:-3] if sym.endswith(".JK") else sym
                if len(ref_symbols)==len(mdf):
                    ref=ref.loc[~ref_symbols.str.replace(r"\.JK$","",regex=True).eq(target_key)]
                if len(ref)<5:
                    continue
                combined=pd.concat([ref,pd.Series([v])],ignore_index=True)
                pct=float(combined.rank(method='average',pct=True).iloc[-1]*100)
                mom_vals.append(pct)
    if len(mom_vals)==4:
        raw=float(np.mean(mom_vals))
        out['raw_momentum_score']=raw
        out['momentum_evidence']='FULL'
        out['evidence_adjustment']=1.0
        out['momentum_score']=raw

    # Risk strength: favorable percentile of the four core risk measures.
    # Lower volatility/loss is better; a less-negative drawdown is better.
    try:
        rd=load(FILES['risk'])
        if isinstance(rd,dict):
            rdf=pd.DataFrame(rd.values())
        else:
            rdf=pd.DataFrame(rd)
    except Exception:
        rdf=pd.DataFrame()
    risk_defs=[
        ('volatility_20d',False),
        ('volatility_60d',False),
        ('max_drawdown_60d',True),
        ('max_daily_loss_20d',True),
    ]
    risk_vals=[]
    for c,higher_better in risk_defs:
        v=n(daily_metrics.get(c))
        if np.isnan(v):
            continue
        if not rdf.empty and c in rdf.columns:
            ref=pd.to_numeric(rdf[c],errors='coerce').dropna()
            if len(ref)>=5:
                ref_symbols=rdf.get("symbol",pd.Series(dtype=str)).astype(str).str.upper().str.strip()
                target_key=sym[:-3] if sym.endswith(".JK") else sym
                if len(ref_symbols)==len(rdf):
                    ref=ref.loc[~ref_symbols.str.replace(r"\.JK$","",regex=True).eq(target_key)]
                if len(ref)<5:
                    continue
                combined=pd.concat([ref,pd.Series([v])],ignore_index=True)
                pct=float(combined.rank(method='average',pct=True).iloc[-1]*100)
                if not higher_better:
                    pct=100.0-pct+(100.0/len(combined))
                risk_vals.append(float(np.clip(pct,0,100)))
    if len(risk_vals)==4:
        strength=float(np.mean(risk_vals))
        out['risk_strength']=strength
        out['risk_score']=100.0-strength
        out['risk_evidence']='FULL'
    return out


def journal_apply_dynamic_scores(row, symbol, daily_metrics):
    """Keep published scores canonical; fill a missing score only with complete live evidence."""
    canonical_score=n(row.get('bagger_score'))
    canonical_signal=row.get('composite_signal')
    canonical_evidence=row.get('evidence_level')
    scores=journal_dynamic_scores(symbol,row,daily_metrics)
    dynamic_used=bool({'momentum_score','risk_strength'} & set(scores))
    for k,v in scores.items():
        row[k]=v
    dims={'growth_score':0.25,'quality_score':0.20,'valuation_score':0.20,'momentum_score':0.20,'risk_strength':0.15}
    vals={k:n(row.get(k)) for k in dims}
    available=sum(np.isfinite(v) for v in vals.values())
    row['available_dimensions']=available
    if np.isfinite(canonical_score):
        row['bagger_score']=canonical_score
        row['composite_signal']=canonical_signal or 'QUANTITATIVE_COMPOSITE'
        row['evidence_level']=canonical_evidence or '—'
        row['journal_score_provenance']='Published Market Intelligence score snapshot; live daily evidence is presented separately.'
    elif available==5 and dynamic_used:
        row['bagger_score']=float(sum(vals[k]*w for k,w in dims.items()))
        row['evidence_level']='MEDIUM'
        row['composite_signal']='QUANTITATIVE_COMPOSITE'
        row['journal_score_provenance']='Journal-only estimate: stored fundamentals and valuation plus daily-price momentum and risk. Market Intelligence has no published score for this company.'
    else:
        row['bagger_score']=np.nan
        row['composite_signal']='INSUFFICIENT_EVIDENCE'
        row['journal_score_provenance']=f'Score unavailable: {available} of 5 required dimensions currently have eligible values.'
    return row



def journal_value(v, suffix='', decimals=1):
    x=n(v)
    if np.isnan(x): return 'N/A'
    return f'{x:.{decimals}f}{suffix}'


def journal_latest_report_eps(report):
    """Return the latest verified EPS from the normalized Company Report."""
    if not isinstance(report, dict):
        return np.nan, None
    raw = report.get('historical_eps') or {}
    if isinstance(raw, dict):
        vals = []
        for year_key, item in raw.items():
            try:
                year = int(year_key)
            except Exception:
                continue
            value = n(item.get('eps')) if isinstance(item, dict) else n(item)
            if np.isfinite(value):
                vals.append((year, value))
        if vals:
            vals.sort(key=lambda x: x[0])
            return vals[-1][1], vals[-1][0]
    return np.nan, None


def journal_forecast(row, years=3, report=None):
    """Build Journal growth scenarios with Sectors Company Report as the preferred source.

    Priority:
      1) Sectors API company_growth_forecasts when present.
      2) RowletAI derived forecast from local YoY growth evidence.

    Sectors forecast points are treated as the Base input; Bear/Bull are RowletAI
    scenario bands around those reported estimates. No historical or forecast values
    are invented beyond the available source points.
    """
    # --- Preferred: verified Sectors Company Report forecast ---
    direct=[]
    if isinstance(report,dict):
        raw=report.get('company_growth_forecasts') or []
        if isinstance(raw,list):
            for item in raw:
                if not isinstance(item,dict):
                    continue
                try:
                    ey=int(item.get('estimate_year'))
                except Exception:
                    continue
                rg=n(item.get('revenue_growth')); eg=n(item.get('eps_growth'))
                if np.isnan(rg) and np.isnan(eg):
                    continue
                if np.isnan(rg): rg=eg
                if np.isnan(eg): eg=rg
                # Keep EPS growth as its own explicit forecast dimension.
                # If the source does not expose a separate EPS field, use the
                # normalized earnings-growth fallback already used by the forecast engine.
                _raw_epsg=n(item.get('eps_growth'))
                epsg=_raw_epsg if np.isfinite(_raw_epsg) else eg
                base=.55*rg+.45*eg
                # Minimum 4 percentage-point scenario spread; wider when the two
                # reported growth inputs disagree.
                spread=max(abs(rg-eg)*.5,.04)
                direct.append({
                    'estimate_year':ey,
                    'base_year':item.get('base_year'),
                    'revenue_growth':rg,
                    'earnings_growth':eg,
                    'eps_growth':epsg,
                    'eps_growth_direct':bool(np.isfinite(_raw_epsg)),
                    'observed':base,
                    'base':base,
                    'bear':base-spread,
                    'bull':base+spread,
                    'scenario_spread':spread,
                })
    if direct:
        direct=sorted(direct,key=lambda x:x['estimate_year'])
        # If duplicate estimate years exist, keep the last normalized source point.
        dedup={}
        for item in direct: dedup[item['estimate_year']]=item
        direct=[dedup[y] for y in sorted(dedup)]
        return {
            'source':'Sectors API',
            'source_detail':'Company Report · company_growth_forecasts',
            'years':[x['estimate_year'] for x in direct],
            'revenue_growth':direct[0]['revenue_growth'],
            'earnings_growth':direct[0]['earnings_growth'],
            'eps_growth':direct[0]['eps_growth'],
            'observed':direct[0]['observed'],
            'bear':[x['bear'] for x in direct],
            'base':[x['base'] for x in direct],
            'bull':[x['bull'] for x in direct],
            'points':direct,
            'is_direct':True,
        }

    # --- Fallback: RowletAI derived forecast from local evidence ---
    rg=n(row.get('yoy_quarter_revenue_growth')); eg=n(row.get('yoy_quarter_earnings_growth'))
    if np.isnan(rg) and np.isnan(eg): return None
    if np.isnan(rg): rg=eg
    if np.isnan(eg): eg=rg
    observed=.55*rg+.45*eg
    spread=max(abs(rg-eg)*.5,.04)
    from datetime import datetime
    start_year=datetime.now().year
    calendar_years=[start_year+i for i in range(years)]
    out={'source':'RowletAI Derived','source_detail':'YoY revenue/earnings evidence · scenario engine',
         'revenue_growth':rg,'earnings_growth':eg,'observed':observed,
         'years':calendar_years,'bear':[],'base':[],'bull':[],
         'points':[],'is_direct':False,'eps_growth_direct':False}
    for i,estimate_year in enumerate(calendar_years, start=1):
        g=observed*(.82**(i-1)); sp=spread*(.85**(i-1))
        out['base'].append(g); out['bear'].append(g-sp); out['bull'].append(g+sp)
        out['points'].append({'estimate_year':estimate_year,'revenue_growth':rg,'earnings_growth':eg,'eps_growth':eg,'eps_growth_direct':False,
                              'observed':g,'base':g,'bear':g-sp,'bull':g+sp,'scenario_spread':sp})
    return out



def journal_scenario_paths(fc, metric='revenue', horizon=3):
    """Single source of truth for the annual Bear/Base/Bull growth paths shown in Section 04.

    Section 04 charts/cards and Section 06 valuation must consume these exact annual
    scenario rates; no second scenario transformation is performed downstream.
    """
    metric=str(metric or 'revenue').lower()
    forecast_key={'revenue':'revenue_growth','earnings':'earnings_growth','eps':'eps_growth'}.get(metric,'revenue_growth')
    points=[p for p in (list(fc.get('points') or []) if isinstance(fc,dict) else []) if isinstance(p,dict)]
    points=sorted(points,key=lambda p: n(p.get('estimate_year')))
    raw_years=list(fc.get('years') or []) if isinstance(fc,dict) else []
    first_year=None
    for candidate in raw_years:
        m=re.search(r'(\d{4})',str(candidate))
        if m:
            first_year=int(m.group(1)); break
    if first_year is None:
        for p in points:
            m=re.search(r'(\d{4})',str(p.get('estimate_year')))
            if m:
                first_year=int(m.group(1)); break
    if first_year is None:
        from datetime import datetime
        first_year=datetime.now().year
    horizon_years=[first_year+i for i in range(max(1,int(horizon)))]

    def source_point_for_year(y):
        for p in points:
            m=re.search(r'(\d{4})',str(p.get('estimate_year')))
            if m and int(m.group(1))==int(y):
                return p
        return points[0] if points else {}

    anchor=source_point_for_year(horizon_years[0])
    anchor_raw=n(anchor.get(forecast_key))
    if metric=='eps' and not np.isfinite(anchor_raw):
        anchor_raw=n(anchor.get('earnings_growth'))
    anchor_spread=n(anchor.get('scenario_spread'))
    if not np.isfinite(anchor_raw):
        for p in points:
            v=n(p.get(forecast_key))
            if metric=='eps' and not np.isfinite(v):
                v=n(p.get('earnings_growth'))
            if np.isfinite(v):
                anchor_raw=v; anchor=p; anchor_spread=n(p.get('scenario_spread')); break

    plotted={'bear':[],'base':[],'bull':[]}
    for idx,y in enumerate(horizon_years):
        p=source_point_for_year(y)
        raw=n(p.get(forecast_key))
        if metric=='eps' and not np.isfinite(raw):
            raw=n(p.get('earnings_growth'))
        spread=n(p.get('scenario_spread'))
        if not np.isfinite(raw):
            raw=anchor_raw*(0.88**idx) if np.isfinite(anchor_raw) else np.nan
        elif idx>0 and points and p is points[0]:
            raw=raw*(0.88**idx)
        if not np.isfinite(spread):
            spread=anchor_spread*(0.85**idx) if np.isfinite(anchor_spread) else np.nan
        elif idx>0 and points and p is points[0]:
            spread=spread*(0.85**idx)
        plotted['base'].append(float(raw) if np.isfinite(raw) else np.nan)
        plotted['bear'].append(float(raw-spread) if np.isfinite(raw) and np.isfinite(spread) else (float(raw) if np.isfinite(raw) else np.nan))
        plotted['bull'].append(float(raw+spread) if np.isfinite(raw) and np.isfinite(spread) else (float(raw) if np.isfinite(raw) else np.nan))
    return {'years':horizon_years,'bear':plotted['bear'],'base':plotted['base'],'bull':plotted['bull'],'anchor':anchor_raw}

def journal_growth_chart(fc, historical=None, metric='revenue'):
    """Render historical growth plus a robust 3-year Bear/Base/Bull path."""
    fig=go.Figure()
    metric=str(metric or 'revenue').lower()
    metric_map={
        'revenue':('Revenue Growth','rev_growth','revenue_growth'),
        'earnings':('Earnings Growth','earn_growth','earnings_growth'),
        'eps':('EPS Growth','eps_growth','eps_growth'),
    }
    metric_label,hist_col,forecast_key=metric_map.get(metric,metric_map['revenue'])

    hist_years=[]; hist_values=[]
    if isinstance(historical,pd.DataFrame) and not historical.empty:
        h=historical.copy()
        for c in ['year','revenue','net_profit','eps']:
            if c in h.columns: h[c]=pd.to_numeric(h[c],errors='coerce')
        h=h.sort_values('year').reset_index(drop=True)
        if 'revenue' in h.columns: h['rev_growth']=h['revenue'].pct_change()
        if 'net_profit' in h.columns: h['earn_growth']=h['net_profit'].pct_change()
        if 'eps' in h.columns: h['eps_growth']=h['eps'].pct_change()
        if hist_col not in h.columns: h[hist_col]=np.nan
        for _,r in h.iterrows():
            y=n(r.get('year')); v=n(r.get(hist_col))
            if np.isfinite(y) and np.isfinite(v):
                hist_years.append(int(y)); hist_values.append(float(v)*100.0)
    if hist_years:
        hist_years=hist_years[-5:]; hist_values=hist_values[-5:]
        fig.add_trace(go.Scatter(x=hist_years,y=hist_values,mode='lines+markers',name='Actual',
            line={'width':3,'color':'#1565C0'},marker={'size':7,'color':'#1565C0','line':{'width':1,'color':'#FFFFFF'}},
            hovertemplate='%{x}: %{y:.1f}%<extra>Actual · '+metric_label+'</extra>'))

    path=journal_scenario_paths(fc, metric=metric, horizon=3)
    horizon_years=path['years']
    plotted={}
    scenario_colors={'bear':'#E53935','base':'#1565C0','bull':'#159447'}
    scenario_names={'bear':'Bear','base':'Base','bull':'Bull'}
    for k in ['bear','base','bull']:
        vals=[float(v)*100.0 if np.isfinite(v) else np.nan for v in path[k]]
        plotted[k]=vals; c=scenario_colors[k]
        fig.add_trace(go.Scatter(x=horizon_years,y=vals,mode='lines+markers',name=scenario_names[k],
            line={'width':3,'color':c},marker={'size':7,'color':c,'line':{'width':1,'color':'#FFFFFF'}},
            hovertemplate='%{x}E: %{y:.1f}%<extra>'+scenario_names[k]+' · '+metric_label+'</extra>'))

    all_x=hist_years+horizon_years
    fig.update_layout(
        height=350,margin=dict(l=52,r=22,t=38,b=54),paper_bgcolor='#FFFFFF',plot_bgcolor='#FFFFFF',
        showlegend=False,hovermode='x unified',
        yaxis=dict(title=dict(text=metric_label,font=dict(size=13,color='#496A86')),ticksuffix='%',showgrid=True,gridcolor='#DCE7F0',zeroline=False,tickfont=dict(size=11,color='#496A86')),
        xaxis=dict(type='linear',showgrid=True,gridcolor='#E2EBF3',tickmode='array',tickvals=all_x,ticktext=[str(y) for y in all_x],title=dict(text='Year',font=dict(size=13,color='#496A86')),tickfont=dict(size=11,color='#496A86'),range=[min(all_x)-0.25,max(all_x)+0.65] if all_x else None),
        font=dict(color='#496A86',family='Arial, sans-serif',size=12))

    if hist_years and horizon_years:
        boundary=horizon_years[0]-0.5
        fig.add_vrect(x0=boundary,x1=horizon_years[-1]+0.55,fillcolor='rgba(235,245,255,.55)',line_width=0,layer='below')
        fig.add_vline(x=boundary,line_width=1.5,line_dash='dash',line_color='rgba(116,145,170,.75)')
        fig.add_annotation(x=boundary+0.12,y=1.03,xref='x',yref='paper',text='Forecast starts',showarrow=False,font=dict(size=11,color='#6A7B89'),xanchor='left')
    final_x=horizon_years[-1]
    for k,label,color in [('bear','Bear','#E53935'),('base','Base','#1565C0'),('bull','Bull','#159447')]:
        vals=plotted.get(k,[])
        if vals and np.isfinite(vals[-1]):
            val=float(vals[-1])
            fig.add_annotation(x=final_x,y=val,text=f'<b>{label}</b> {val:.1f}%',showarrow=False,xshift=10,xanchor='left',font=dict(size=11,color='#FFFFFF'),bgcolor=color,bordercolor=color,borderpad=5,opacity=.96)
    if hist_years and hist_values:
        fig.add_annotation(x=hist_years[-1],y=hist_values[-1],text=f'<b>{hist_values[-1]:.1f}%</b>',showarrow=False,yshift=16,font=dict(size=10,color='#174D7A'),bgcolor='#EAF3FF',bordercolor='#D1E3F5',borderpad=4)
    return fig

def journal_report_fundamental_df(report):
    """Build verified historical Revenue / Net Profit / EPS series from Sectors Company Report.

    No values are interpolated or synthesized. Each point comes directly from the
    normalized Company Report cache.
    """
    if not isinstance(report,dict):
        return pd.DataFrame(columns=['year','revenue','net_profit','eps'])
    fin=report.get('historical_financials') or []
    eps_raw=report.get('historical_eps') or {}
    rows=[]
    if isinstance(fin,list):
        for item in fin:
            if not isinstance(item,dict):
                continue
            year=item.get('year')
            try: year=int(year)
            except Exception: continue
            eps_item=eps_raw.get(str(year),{}) if isinstance(eps_raw,dict) else {}
            eps_value=eps_item.get('eps') if isinstance(eps_item,dict) else eps_item
            rows.append({
                'year':year,
                'revenue':n(item.get('revenue')),
                'net_profit':n(item.get('earnings')),
                'eps':n(eps_value),
            })
    # EPS can contain a verified year not present in historical_financials.
    if isinstance(eps_raw,dict):
        existing={r['year'] for r in rows}
        for year_key,item in eps_raw.items():
            try: year=int(year_key)
            except Exception: continue
            if year in existing or not isinstance(item,dict):
                continue
            rows.append({'year':year,'revenue':np.nan,'net_profit':np.nan,'eps':n(item.get('eps'))})
    if not rows:
        return pd.DataFrame(columns=['year','revenue','net_profit','eps'])
    out=pd.DataFrame(rows).drop_duplicates(subset=['year'],keep='last').sort_values('year')
    return out.reset_index(drop=True)


def journal_fundamental_forecast_df(report, historical, row=None, years=3):
    """Build a transparent 3-year level forecast for Revenue, Net Profit and EPS.

    Priority:
      1) Sectors Company Report company_growth_forecasts for Revenue growth and EPS growth.
      2) Latest measured YoY revenue/earnings growth from the Journal row.

    Forecast levels are compounded from the latest verified historical value.
    Net Profit uses the earnings/EPS growth rate as a proxy only when no direct
    net-profit forecast is supplied; the UI labels that assumption explicitly.
    No forecast is used in Bagger scoring.
    """
    empty=pd.DataFrame(columns=['year','revenue','net_profit','eps','kind'])
    if not isinstance(historical,pd.DataFrame) or historical.empty:
        return empty, {'source':'Unavailable','detail':'Verified historical base values are not available.'}

    h=historical.copy()
    for c in ['year','revenue','net_profit','eps']:
        if c in h:
            h[c]=pd.to_numeric(h[c],errors='coerce')
    h=h.sort_values('year').reset_index(drop=True)
    if 'year' not in h or h['year'].dropna().empty:
        return empty, {'source':'Unavailable','detail':'Verified historical years are not available.'}

    # Last verified value for each metric. We do not backfill missing historical values.
    last_year=int(h['year'].dropna().iloc[-1])
    base={}
    for c in ['revenue','net_profit','eps']:
        valid=h[['year',c]].dropna(subset=[c]) if c in h else pd.DataFrame()
        if valid.empty:
            base[c]=np.nan
        else:
            base[c]=float(valid.iloc[-1][c])

    # Prefer Sectors Company Report forecast points.
    growth_points=[]
    if isinstance(report,dict):
        raw=report.get('company_growth_forecasts') or []
        if isinstance(raw,list):
            for item in raw:
                if not isinstance(item,dict):
                    continue
                try:
                    ey=int(item.get('estimate_year'))
                except Exception:
                    continue
                if ey<=last_year:
                    continue
                rg=n(item.get('revenue_growth'))
                eg=n(item.get('eps_growth'))
                # Some payloads may expose earnings growth under another key.
                if np.isnan(eg): eg=n(item.get('earnings_growth'))
                if np.isnan(rg) and np.isnan(eg):
                    continue
                if np.isnan(rg): rg=eg
                if np.isnan(eg): eg=rg
                growth_points.append({'year':ey,'revenue_growth':rg,'earnings_growth':eg,'source':'Sectors API'})

    growth_points=sorted(growth_points,key=lambda x:x['year'])
    # Deduplicate by year while preserving the latest source point.
    dedup={x['year']:x for x in growth_points}
    growth_points=[dedup[y] for y in sorted(dedup)]

    source='Sectors API' if growth_points else 'RowletAI Derived'
    if not growth_points:
        rg=n(row.get('yoy_quarter_revenue_growth')) if isinstance(row,dict) or hasattr(row,'get') else np.nan
        eg=n(row.get('yoy_quarter_earnings_growth')) if isinstance(row,dict) or hasattr(row,'get') else np.nan
        if np.isnan(rg) and np.isnan(eg):
            return empty, {'source':'Unavailable','detail':'No forward growth evidence is available.'}
        if np.isnan(rg): rg=eg
        if np.isnan(eg): eg=rg
        # Dampen the latest YoY evidence across the horizon. This avoids simply
        # extending a single quarterly growth spike for three full years.
        for i in range(1,years+1):
            ey=last_year+i
            damping=0.85**(i-1)
            growth_points.append({'year':ey,'revenue_growth':rg*damping,'earnings_growth':eg*damping,'source':'RowletAI Derived'})

    # Always present exactly the next three forecast years when enough evidence exists.
    growth_points=growth_points[:years]
    if len(growth_points)<years:
        # Extend only the last available forecast rate with the same dampening rule;
        # this is explicitly derived, not presented as company guidance.
        if growth_points:
            last=growth_points[-1]
            for i in range(len(growth_points)+1,years+1):
                damping=0.85**(i-len(growth_points))
                growth_points.append({'year':last_year+i,
                                      'revenue_growth':last['revenue_growth']*damping,
                                      'earnings_growth':last['earnings_growth']*damping,
                                      'source':'RowletAI Derived extension'})
        else:
            return empty, {'source':'Unavailable','detail':'Three forward forecast points could not be established.'}

    # If the API forecast starts later than the immediate next year, align the
    # displayed horizon to the next three calendar years and use the first available
    # reported rate for any missing bridge year, marked as derived.
    by_year={x['year']:x for x in growth_points}
    aligned=[]
    prior=None
    for i in range(1,years+1):
        ey=last_year+i
        if ey in by_year:
            point=by_year[ey].copy()
            prior=point
        elif prior is not None:
            point={'year':ey,
                   'revenue_growth':prior['revenue_growth']*.85,
                   'earnings_growth':prior['earnings_growth']*.85,
                   'source':'RowletAI Derived bridge'}
        else:
            point={'year':ey,
                   'revenue_growth':np.nan,
                   'earnings_growth':np.nan,
                   'source':'Unavailable'}
        aligned.append(point)

    out=[]
    prev_rev=base['revenue']; prev_np=base['net_profit']; prev_eps=base['eps']
    for point in aligned:
        rg=point['revenue_growth']; eg=point['earnings_growth']
        if np.isfinite(prev_rev) and np.isfinite(rg):
            prev_rev=prev_rev*(1+rg)
        else:
            prev_rev=np.nan
        if np.isfinite(prev_eps) and np.isfinite(eg):
            prev_eps=prev_eps*(1+eg)
        else:
            prev_eps=np.nan
        # No direct net-profit forecast field is currently normalized. Use the
        # earnings/EPS growth proxy and expose that assumption in the source note.
        if np.isfinite(prev_np) and np.isfinite(eg):
            prev_np=prev_np*(1+eg)
        else:
            prev_np=np.nan
        out.append({'year':int(point['year']),'revenue':prev_rev,'net_profit':prev_np,'eps':prev_eps,'kind':'Forecast',
                    'revenue_growth':rg,'earnings_growth':eg,'growth_source':point['source']})

    hist=h[['year','revenue','net_profit','eps']].copy()
    hist['kind']='Actual'
    for c in ['revenue','net_profit','eps']:
        if c not in hist: hist[c]=np.nan
    hist=hist[['year','revenue','net_profit','eps','kind']]
    combined=pd.concat([hist,pd.DataFrame(out)[['year','revenue','net_profit','eps','kind']]],ignore_index=True)
    detail=('Revenue and EPS are compounded from the latest verified historical values using '
            'forward growth evidence. Net Profit is derived with the earnings/EPS growth proxy '
            'because the normalized Company Report does not currently expose a direct net-profit forecast.')
    if source!='Sectors API':
        detail+=' RowletAI fallback dampens the latest YoY growth evidence across the three-year horizon.'
    return combined, {'source':source,'detail':detail,'last_actual_year':last_year,'forecast_years':[x['year'] for x in aligned]}


def journal_fundamental_forecast_chart(frame, value_col, name, unit='money'):
    """Render the approved Fundamental Performance chart: actual history + 3-year forward forecast."""
    if frame.empty or value_col not in frame:
        return journal_empty_chart(name.upper(),'Verified historical series and forecast are not available.')
    x=frame[['year',value_col,'kind']].copy()
    x[value_col]=pd.to_numeric(x[value_col],errors='coerce')
    x=x.dropna(subset=[value_col]).sort_values(['year','kind'])
    if x.empty:
        return journal_empty_chart(name.upper(),'Verified historical series and forecast are not available.')
    actual=x[x['kind'].eq('Actual')].copy()
    forecast=x[x['kind'].eq('Forecast')].copy()
    all_y=pd.to_numeric(x[value_col],errors='coerce').astype(float)
    maxv=float(all_y.abs().max()) if len(all_y) else 0.0
    if unit=='eps':
        display=lambda df: pd.to_numeric(df[value_col],errors='coerce')
        axis_title='Rp / share'; hover_unit='Rp %{y:,.2f}'
    elif maxv>=1e12:
        display=lambda df: pd.to_numeric(df[value_col],errors='coerce')/1e12
        axis_title='Rp T'; hover_unit='Rp %{y:,.2f}T'
    elif maxv>=1e9:
        display=lambda df: pd.to_numeric(df[value_col],errors='coerce')/1e9
        axis_title='Rp B'; hover_unit='Rp %{y:,.2f}B'
    else:
        display=lambda df: pd.to_numeric(df[value_col],errors='coerce')
        axis_title='Rp'; hover_unit='Rp %{y:,.0f}'
    fig=go.Figure()
    if not actual.empty:
        fig.add_trace(go.Scatter(x=actual['year'],y=display(actual),mode='lines+markers',name='Actual',
                                 line={'width':2.8},marker={'size':6},
                                 hovertemplate='%{x}: '+hover_unit+'<extra>Actual</extra>'))
    if not forecast.empty:
        fig.add_trace(go.Scatter(x=forecast['year'],y=display(forecast),mode='lines+markers',name='Forecast',
                                 line={'width':2.8,'dash':'dot'},marker={'size':6},
                                 hovertemplate='%{x}E: '+hover_unit+'<extra>Forecast</extra>'))
        if not actual.empty:
            boundary=float(actual['year'].max())+0.5
            fig.add_vline(x=boundary,line_width=1.3,line_dash='dash',line_color='rgba(104,132,153,.55)')
            fig.add_annotation(x=boundary+0.12,y=1.02,xref='x',yref='paper',text='Forecast<br>(2026E–2028E)',showarrow=False,
                               font=dict(size=10,color='#6A8196'),xanchor='left',align='left')
    fig.update_layout(height=245,margin=dict(l=12,r=12,t=32,b=22),paper_bgcolor='rgba(0,0,0,0)',
                      plot_bgcolor='#FFFFFF',showlegend=True,hovermode='x unified',
                      legend=dict(orientation='h',y=1.10,x=0,font=dict(size=10,color='#4F6F89')),
                      font=dict(family='Arial',size=10,color='#607B92'))
    fig.update_xaxes(title=None,dtick=1,showgrid=True,gridcolor='rgba(221,231,239,.65)',zeroline=False,
                     tickfont=dict(size=10,color='#668097'))
    fig.update_yaxes(title=axis_title,showgrid=True,gridcolor='rgba(221,231,239,.65)',zeroline=False,
                     tickfont=dict(size=10,color='#668097'),title_font=dict(size=10,color='#607B92'))
    return fig


def journal_fundamental_kpi_html(frame, value_col, unit='money'):
    """Compact latest-actual / first-forecast / CAGR summary beneath a fundamental chart."""
    if frame.empty or value_col not in frame:
        return ''
    x=frame[['year',value_col,'kind']].copy()
    x[value_col]=pd.to_numeric(x[value_col],errors='coerce')
    x=x.dropna(subset=[value_col]).sort_values(['year','kind'])
    actual=x[x['kind'].eq('Actual')]; forecast=x[x['kind'].eq('Forecast')]
    if actual.empty or forecast.empty:
        return ''
    last=actual.iloc[-1]; prev=actual.iloc[-2] if len(actual)>=2 else None
    first_f=forecast.iloc[0]; last_f=forecast.iloc[-1]
    lv=float(last[value_col]); fv=float(first_f[value_col]); endv=float(last_f[value_col])
    def scale(v):
        av=abs(float(v))
        if unit=='eps': return f'Rp {v:,.0f}'
        if av>=1e12: return f'Rp {v/1e12:,.1f} T'
        if av>=1e9: return f'Rp {v/1e9:,.1f} B'
        return f'Rp {v:,.0f}'
    def pct(v): return f'{v:+.1f}%'
    yoy_actual=((lv/float(prev[value_col]))-1)*100 if prev is not None and float(prev[value_col])!=0 else None
    yoy_forecast=((fv/lv)-1)*100 if lv!=0 else None
    n_years=max(1,int(last_f['year'])-int(last['year']))
    cagr=((endv/lv)**(1/n_years)-1)*100 if lv>0 and endv>0 else None
    def change_html(v):
        if v is None: return '<span class="j-fund-kpi-muted">N/A</span>'
        cls='positive' if v>=0 else 'negative'
        return f'<span class="j-fund-kpi-change {cls}">{pct(v)}</span>'
    actual_year=int(last['year']); first_year=int(first_f['year']); end_year=int(last_f['year'])
    return f'''<div class="j-fund-kpi-row">
        <div class="j-fund-kpi-cell"><div class="j-fund-kpi-label">{actual_year}</div><div class="j-fund-kpi-value">{scale(lv)}</div>{change_html(yoy_actual)}<div class="j-fund-kpi-sub">vs {int(prev['year']) if prev is not None else 'prior year'}</div></div>
        <div class="j-fund-kpi-cell"><div class="j-fund-kpi-label">{first_year}E</div><div class="j-fund-kpi-value">{scale(fv)}</div>{change_html(yoy_forecast)}<div class="j-fund-kpi-sub">vs {actual_year}</div></div>
        <div class="j-fund-kpi-cell j-fund-kpi-cagr"><div class="j-fund-kpi-label">CAGR {actual_year}–{end_year}E</div>{change_html(cagr)}<div class="j-fund-kpi-sub">3-year forward</div></div>
    </div>'''

def journal_fundamental_chart(frame, value_col, name, unit='auto'):
    """Render one compact historical fundamental series with verified points only."""
    if frame.empty or value_col not in frame:
        return journal_empty_chart(name.upper(),'Verified historical series is not available.')
    x=frame[['year',value_col]].copy()
    x[value_col]=pd.to_numeric(x[value_col],errors='coerce')
    x=x.dropna(subset=[value_col])
    if x.empty:
        return journal_empty_chart(name.upper(),'Verified historical series is not available.')

    fig=go.Figure()
    fig.add_trace(go.Scatter(
        x=x['year'], y=x[value_col], mode='lines+markers', name=name,
        line={'width':2.5}, marker={'size':6},
        hovertemplate='%{x}: %{y:,.2f}<extra>'+name+'</extra>'
    ))
    if unit=='eps':
        suffix=' EPS'
        hover='Rp %{y:,.2f}'
    else:
        suffix=''
        hover=None
    if unit in ('money','auto'):
        # Display large corporate financials in Rp T for readability while
        # retaining the raw API values in the hover tooltip.
        if float(x[value_col].abs().max()) >= 1e12:
            display=x[value_col]/1e12
            fig.data[0].y=display
            fig.data[0].hovertemplate='%{x}: Rp %{y:,.2f}T<extra>'+name+'</extra>'
            axis_title='Rp T'
        elif float(x[value_col].abs().max()) >= 1e9:
            display=x[value_col]/1e9
            fig.data[0].y=display
            fig.data[0].hovertemplate='%{x}: Rp %{y:,.2f}B<extra>'+name+'</extra>'
            axis_title='Rp B'
        else:
            display=x[value_col]
            fig.data[0].y=display
            fig.data[0].hovertemplate='%{x}: Rp %{y:,.0f}<extra>'+name+'</extra>'
            axis_title='Rp'
    elif unit=='eps':
        fig.data[0].hovertemplate='%{x}: Rp %{y:,.2f}<extra>'+name+'</extra>'
        axis_title='Rp / share'
    else:
        axis_title=''

    fig.update_layout(
        height=185, margin=dict(l=8,r=8,t=10,b=8),
        paper_bgcolor='rgba(0,0,0,0)', plot_bgcolor='rgba(255,255,255,.35)',
        showlegend=False, hovermode='x unified',
        xaxis=dict(title=None, dtick=1, showgrid=False),
        yaxis=dict(title=axis_title, showgrid=True, gridcolor='rgba(216,228,238,.55)', zeroline=False),
    )
    return fig


def journal_price_chart(h):
    fig=go.Figure()
    fig.add_trace(go.Scatter(x=h['date'],y=h['close'],mode='lines',name='Price',line={'width':2.5}))
    if 'MA20' in h.columns:
        fig.add_trace(go.Scatter(x=h['date'],y=h['MA20'],mode='lines',name='MA20',line={'width':1.4}))
    if 'MA60' in h.columns:
        fig.add_trace(go.Scatter(x=h['date'],y=h['MA60'],mode='lines',name='MA60',line={'width':1.4}))
    fig.update_layout(height=250,margin=dict(l=8,r=8,t=8,b=8),paper_bgcolor='rgba(0,0,0,0)',plot_bgcolor='rgba(255,255,255,.35)',legend=dict(orientation='h',y=1.12,x=0),hovermode='x unified')
    return fig


def journal_price_simulation_chart(h, current_price, scenario_vals, forecast_years=None, horizon_years=3):
    """Historical observed price + selected-horizon illustrative scenario paths."""
    fig=go.Figure(); hist=h.copy() if isinstance(h,pd.DataFrame) else pd.DataFrame()
    if not hist.empty and 'date' in hist.columns and 'close' in hist.columns:
        hist['date']=pd.to_datetime(hist['date'],errors='coerce'); hist['close']=pd.to_numeric(hist['close'],errors='coerce'); hist=hist.dropna(subset=['date','close']).sort_values('date')
    if not hist.empty:
        fig.add_trace(go.Scatter(x=hist['date'],y=hist['close'],mode='lines',name='Historical Price',line=dict(color='#0B6FD3',width=3),hovertemplate='%{x|%d %b %Y}: Rp %{y:,.0f}<extra>Historical price</extra>'))
    if current_price is None or not np.isfinite(n(current_price)):
        fig.update_layout(height=455,margin=dict(l=62,r=25,t=24,b=48),paper_bgcolor='#FFFFFF',plot_bgcolor='#FFFFFF',showlegend=False); return fig
    cp=float(current_price); today=hist['date'].max() if not hist.empty else pd.Timestamp.today().normalize(); years=max(1,int(horizon_years)); target=today+pd.DateOffset(years=years)
    colors={'Bear':'#E53935','Base':'#1769E0','Bull':'#0B8F55'}; fills={'Bear':'#FFF1F1','Base':'#EEF5FF','Bull':'#EDF9F2'}; borders={'Bear':'#F0A4A8','Base':'#A8C8F2','Bull':'#A9D9BD'}
    progress=np.array([0,.20,.48,.73,1.0]); dates=[today]+[today+pd.DateOffset(months=int(years*12*p)) for p in [.25,.50,.75,1.0]]
    for name in ['Bear','Base','Bull']:
        target_y=n(scenario_vals.get(name))
        if not np.isfinite(target_y): continue
        y=cp+(target_y-cp)*progress
        fig.add_trace(go.Scatter(x=dates,y=y,mode='lines',name=name,line=dict(color=colors[name],width=2.8,dash='dash'),hovertemplate='%{x|%d %b %Y}: Rp %{y:,.0f}<extra>'+name+' scenario</extra>'))
        fig.add_trace(go.Scatter(x=[target],y=[target_y],mode='markers',showlegend=False,marker=dict(size=12,color=colors[name],line=dict(color='#fff',width=2)),hovertemplate=f'{name} target: Rp %{{y:,.0f}}<extra></extra>'))
        ret=(target_y/cp-1)*100 if cp>0 else np.nan; ret_txt=('+' if ret>=0 else '')+f'{ret:.1f}%'
        fig.add_annotation(x=target,y=target_y,text=f'<b>{name}</b><br><b>Rp {target_y:,.0f}</b><br>{ret_txt}',showarrow=False,xanchor='left',xshift=10,font=dict(size=12,color=colors[name]),bgcolor=fills[name],bordercolor=borders[name],borderwidth=1,borderpad=6,align='left')
    fig.add_trace(go.Scatter(x=[today],y=[cp],mode='markers',showlegend=False,marker=dict(size=12,color='#173F66',line=dict(color='#fff',width=2)),hovertemplate='Today: Rp %{y:,.0f}<extra></extra>'))
    fig.add_annotation(x=today,y=cp,text=f'<b>Today</b><br><b>Rp {cp:,.0f}</b>',showarrow=False,yshift=45,font=dict(size=11,color='#173F66'),bgcolor='#fff',bordercolor='#B8D0E5',borderwidth=1,borderpad=6)
    fig.update_layout(shapes=[dict(type='rect',xref='x',yref='paper',x0=today,x1=target,y0=0,y1=1,fillcolor='#F3F8FE',opacity=.8,line_width=0,layer='below'),dict(type='line',xref='x',yref='paper',x0=today,x1=today,y0=0,y1=1,line=dict(color='rgba(72,105,132,.65)',width=1.5,dash='dash')),dict(type='line',xref='x',yref='paper',x0=target,x1=target,y0=0,y1=1,line=dict(color='rgba(72,105,132,.3)',width=1,dash='dot'),layer='below')])
    # Keep the Historical label inside the actual historical-price region (left of Today),
    # rather than placing it over the simulation area.
    hist_start = hist['date'].min() if not hist.empty else today-pd.DateOffset(months=12)
    hist_label_x = hist_start + (today-hist_start)*0.52
    fig.add_annotation(x=hist_label_x,y=.93,xref='x',yref='paper',text='<b>← Historical</b>',showarrow=False,font=dict(size=13,color='#173F66'))
    fig.add_annotation(x=today+(target-today)*0.56,y=.93,xref='x',yref='paper',text=f'<b>Simulation ({years} Years) →</b>',showarrow=False,font=dict(size=13,color='#173F66'))
    fig.add_annotation(x=target,y=.04,xref='x',yref='paper',text=f'<b>{years}Y<br>(Target)</b>',showarrow=False,font=dict(size=10,color='#496A86'))
    # Place the color legend below the plot so it does not compete with the chart annotations.
    fig.update_layout(height=455,margin=dict(l=68,r=42,t=30,b=86),paper_bgcolor='#FFFFFF',plot_bgcolor='#FFFFFF',showlegend=True,hovermode='x unified',font=dict(family='Inter, Arial, sans-serif',color='#173E61'),legend=dict(orientation='h',x=.02,y=-.16,yanchor='top',font=dict(size=11,color='#365A7D')),xaxis=dict(showgrid=True,gridcolor='#E3ECF4',tickfont=dict(size=12,color='#5F7180'),range=[hist_start,target+pd.DateOffset(months=2)]),yaxis=dict(title=dict(text='Price (Rp)',font=dict(size=12,color='#496A86')),showgrid=True,gridcolor='#E3ECF4',tickfont=dict(size=12,color='#647787'),zeroline=False))
    return fig


def journal_pct(v, decimals=1):
    """Format decimal ratios consistently; e.g. 0.197169 becomes 19.7%."""
    x=n(v)
    if np.isnan(x): return 'N/A'
    x*=100
    precision=decimals if x==0 or abs(x)>=1 else max(2,decimals)
    return f'{x:.{precision}f}%'


def journal_coverage(row):
    total=5
    available=n(row.get('available_dimensions'))
    if np.isnan(available):
        fields=[row.get(k) for k in ['growth_score','quality_score','valuation_score','momentum_score','risk_strength']]
        available=sum(not np.isnan(n(v)) for v in fields)
    available=int(max(0,min(total,available)))
    return available,total,available/total*100


def journal_risk_interpretation(key, value):
    """Return a deterministic, descriptive interpretation for a risk metric.
    Thresholds are intentionally simple and consistent across the Journal.
    Values are interpreted in decimal form (e.g. 0.35 = 35%).
    """
    x=n(value)
    if np.isnan(x):
        return 'N/A'
    if key in ('volatility_20d','volatility_60d'):
        if x < 0.20:
            return 'Lower variability'
        if x < 0.35:
            return 'Moderate variability'
        return 'Elevated variability'
    if key == 'max_drawdown_60d':
        if x > -0.05:
            return 'Limited drawdown'
        if x > -0.15:
            return 'Moderate drawdown'
        return 'Deep drawdown'
    if key == 'max_daily_loss_20d':
        if x > -0.03:
            return 'Limited daily loss'
        if x > -0.05:
            return 'Moderate daily loss'
        return 'Large daily loss'
    return 'Risk evidence'


def journal_signal_interpretation(key, value):
    """Return a deterministic, descriptive interpretation for catalyst/signal evidence."""
    x=n(value)
    if np.isnan(x):
        return 'N/A'
    if key in ('yoy_quarter_revenue_growth','yoy_quarter_earnings_growth'):
        if x >= 0.25:
            return 'High positive growth'
        if x > 0.05:
            return 'Positive growth'
        if x >= -0.05:
            return 'Broadly stable'
        return 'Negative growth'
    if key in ('return_20d','return_60d'):
        if x >= 0.05:
            return 'Positive momentum'
        if x <= -0.05:
            return 'Negative momentum'
        return 'Near-flat momentum'
    return 'Measured signal'


def journal_dynamic_model_interpretation(row, cov_n=None, cov_t=5):
    """Build a concise, evidence-led interpretation from the current Journal row.
    This is descriptive synthesis only; it does not turn signals into a buy/sell recommendation.
    """
    if cov_n is None:
        cov_n, cov_t, _ = journal_coverage(row)

    def score_label(name, key):
        value = n(row.get(key))
        return f"{name} {value:.1f}" if np.isfinite(value) else None

    parts = []

    if cov_n >= cov_t:
        parts.append(f"All {cov_t} quantitative evidence layers are currently available.")
    else:
        missing = []
        for label, key in [
            ("Growth", "growth_score"),
            ("Quality", "quality_score"),
            ("Valuation", "valuation_score"),
            ("Momentum", "momentum_score"),
            ("Risk", "risk_strength"),
        ]:
            if not np.isfinite(n(row.get(key))):
                missing.append(label)
        if missing:
            parts.append(f"Quantitative evidence currently covers {cov_n} of {cov_t} dimensions; {', '.join(missing)} evidence {'is' if len(missing)==1 else 'are'} not available.")
        else:
            parts.append(f"Quantitative evidence currently covers {cov_n} of {cov_t} dimensions.")

    growth = n(row.get('growth_score'))
    valuation = n(row.get('valuation_score'))
    risk = n(row.get('risk_strength'))
    ret20 = n(row.get('return_20d'))
    ret60 = n(row.get('return_60d'))
    div_yield = n(row.get('yield_ttm'))

    scored = []
    if np.isfinite(growth): scored.append(f"Growth {growth:.1f}")
    if np.isfinite(valuation): scored.append(f"Valuation {valuation:.1f}")
    if np.isfinite(risk): scored.append(f"Risk {risk:.1f}")
    if scored:
        parts.append("Available model scores: " + ", ".join(scored) + ".")

    if np.isfinite(ret20) and np.isfinite(ret60):
        if ret20 < 0 and ret60 > 0:
            parts.append(f"Momentum is mixed across horizons: 20D {ret20*100:.1f}% versus 60D {ret60*100:.1f}%.")
        elif ret20 > 0 and ret60 < 0:
            parts.append(f"Momentum is mixed across horizons: 20D {ret20*100:.1f}% versus 60D {ret60*100:.1f}%.")
        else:
            direction = "positive" if ret20 > 0 and ret60 > 0 else "negative" if ret20 < 0 and ret60 < 0 else "flat/mixed"
            parts.append(f"Momentum is {direction} across the measured 20D and 60D horizons: {ret20*100:.1f}% and {ret60*100:.1f}%.")
    elif np.isfinite(ret20):
        parts.append(f"Measured 20D momentum is {ret20*100:.1f}%; the 60D momentum series is not currently available.")
    elif np.isfinite(ret60):
        parts.append(f"Measured 60D momentum is {ret60*100:.1f}%; the 20D momentum series is not currently available.")

    if np.isfinite(div_yield):
        parts.append(f"Dividend yield evidence is {div_yield*100:.1f}% TTM.")

    parts.append("Forward scenarios are kept separate from measured signals, and unavailable source evidence is not inferred.")
    return " ".join(parts)



def journal_dynamic_conclusion(row, symbol, cov_n=None, cov_t=5):
    """Create evidence-led, ticker-specific conclusion text from measured Journal data."""
    if cov_n is None:
        cov_n, cov_t, _ = journal_coverage(row)

    def val(key):
        return n(row.get(key))

    # Evidence coverage
    coverage = f"{cov_n} of {cov_t}"
    thesis_parts = [f"{symbol} currently has quantitative evidence across {coverage} Bagger dimensions."]

    # Identify the strongest available measured score layers without turning them into a recommendation.
    score_items = [
        ("Growth", val("growth_score")),
        ("Quality", val("quality_score")),
        ("Valuation", val("valuation_score")),
        ("Risk", val("risk_score")),
        ("Momentum", val("momentum_score")),
    ]
    score_items = [(name, value) for name, value in score_items if np.isfinite(value)]
    if score_items:
        ordered = sorted(score_items, key=lambda x: x[1], reverse=True)
        top = ordered[:2]
        thesis_parts.append("Highest displayed evidence scores are " + ", ".join(f"{name} {value:.1f}" for name, value in top) + ".")

    # Momentum interpretation from the measured daily series.
    ret20 = val("return_20d")
    ret60 = val("return_60d")
    if np.isfinite(ret20) and np.isfinite(ret60):
        if ret20 < 0 < ret60 or ret60 < 0 < ret20:
            thesis_parts.append(f"Measured momentum is mixed across horizons: 20D {ret20*100:.1f}% and 60D {ret60*100:.1f}%.")
        elif ret20 > 0 and ret60 > 0:
            thesis_parts.append(f"Measured momentum is positive across both horizons: 20D {ret20*100:.1f}% and 60D {ret60*100:.1f}%.")
        elif ret20 < 0 and ret60 < 0:
            thesis_parts.append(f"Measured momentum is negative across both horizons: 20D {ret20*100:.1f}% and 60D {ret60*100:.1f}%.")
        else:
            thesis_parts.append(f"Measured momentum is near flat across the available horizons: 20D {ret20*100:.1f}% and 60D {ret60*100:.1f}%.")

    div_yield = val("yield_ttm")
    if np.isfinite(div_yield):
        thesis_parts.append(f"TTM dividend yield evidence is {div_yield*100:.1f}%.")

    thesis_parts.append("Forward scenarios are model estimates and are presented separately from measured historical and market signals.")

    # Build watch items from the measured state of the selected company.
    # The wording is intentionally evidence-led: it identifies what to monitor
    # without turning the synthesis into a buy/sell recommendation.
    watch = []
    vol20 = val("volatility_20d")
    vol60 = val("volatility_60d")
    dd60 = val("max_drawdown_60d")
    growth = val("growth_score")
    eps_growth = val("yoy_quarter_earnings_growth")
    rev_growth = val("yoy_quarter_revenue_growth")
    pe = val("pe_ttm")
    fpe = val("forward_pe")
    payout = val("payout_ratio")
    risk = val("risk_strength")
    valuation = val("valuation_score")

    # Momentum: distinguish persistence, mixed direction, and recovery.
    if np.isfinite(ret20) and np.isfinite(ret60):
        if ret20 < 0 < ret60 or ret60 < 0 < ret20:
            watch.append("momentum direction across 20D and 60D")
        elif ret20 > 0 and ret60 > 0:
            watch.append("momentum persistence across 20D and 60D")
        elif ret20 < 0 and ret60 < 0:
            watch.append("momentum recovery across 20D and 60D")
        else:
            watch.append("momentum trend")
    elif np.isfinite(ret20) or np.isfinite(ret60):
        watch.append("momentum coverage and persistence")

    # Risk: elevate the wording when measured volatility/drawdown is notable.
    if np.isfinite(vol20) or np.isfinite(vol60) or np.isfinite(dd60):
        elevated_vol = (np.isfinite(vol20) and vol20 >= 0.35) or (np.isfinite(vol60) and vol60 >= 0.35)
        elevated_dd = np.isfinite(dd60) and dd60 <= -0.15
        if elevated_vol or elevated_dd:
            watch.append("volatility and drawdown")
        elif np.isfinite(risk) and risk < 50:
            watch.append("risk-strength trend")
        else:
            watch.append("risk metrics trend")

    # Fundamental trend: distinguish strong growth that needs confirmation from
    # weak/negative growth that needs recovery evidence.
    if np.isfinite(rev_growth) or np.isfinite(eps_growth) or np.isfinite(growth):
        growth_values = [x for x in (rev_growth, eps_growth) if np.isfinite(x)]
        if growth_values and min(growth_values) < 0:
            watch.append("revenue and earnings recovery")
        elif growth_values and max(growth_values) >= 0.25:
            watch.append("revenue and earnings growth sustainability")
        else:
            watch.append("revenue and earnings trend")

    # Valuation remains a monitoring item when a multiple or valuation score is
    # available, with wording tied to the current evidence state.
    if np.isfinite(pe) or np.isfinite(fpe) or np.isfinite(valuation):
        if np.isfinite(valuation) and valuation >= 70:
            watch.append("valuation multiple changes")
        elif np.isfinite(valuation) and valuation < 50:
            watch.append("valuation re-rating evidence")
        else:
            watch.append("valuation multiple changes")

    # Dividend: focus on sustainability when payout is elevated, otherwise on
    # the persistence of the observed yield/dividend evidence.
    if np.isfinite(payout) or np.isfinite(div_yield):
        if np.isfinite(payout) and payout >= 0.80:
            watch.append("payout ratio and dividend sustainability")
        else:
            watch.append("dividend sustainability")

    # Add evidence gaps only when they genuinely exist.
    if not np.isfinite(val("eps")) and not np.isfinite(val("eps_ttm")):
        watch.append("EPS evidence")

    # Cash-flow coverage has three distinct states:
    # 1) available -> do not flag as a gap;
    # 2) methodology not applicable (banks) -> do not flag;
    # 3) source input genuinely missing for a non-bank -> flag as an evidence gap.
    # A non-positive cash payout ratio is also a methodology/data-state issue,
    # not missing evidence, so it must not create a watch item.
    _watch_industry = str(row.get("industry", "")).lower()
    _watch_sector = str(row.get("sector", "")).lower()
    _watch_is_bank = ("bank" in _watch_industry or "bank" in _watch_sector)
    _watch_cash_payout = val("cash_payout_ratio")
    if (not _watch_is_bank) and (not np.isfinite(_watch_cash_payout)):
        watch.append("cash-flow coverage evidence")

    if not watch:
        watch = ["new fundamental updates", "market price and momentum changes", "valuation changes"]

    # Keep the list concise and unique.
    seen = set()
    watch = [x for x in watch if not (x in seen or seen.add(x))][:5]
    watch_text = " · ".join(watch)

    return " ".join(thesis_parts), watch_text


def _journal_load_env_file():
    """Load local .env files from the project, app and current working directory."""
    candidates = []
    for base in (ROOT, ROOT / "app", Path.cwd(), Path.cwd().parent):
        try:
            f = Path(base) / ".env"
            if f not in candidates:
                candidates.append(f)
        except Exception:
            pass
    for env_file in candidates:
        if not env_file.exists():
            continue
        try:
            for raw_line in env_file.read_text(encoding="utf-8-sig").splitlines():
                line = raw_line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                # Accept optional `export KEY=value` and ignore inline comments only
                # when they are outside a quoted value.
                key, value = line.split("=", 1)
                key = key.strip()
                if key.lower().startswith("export "):
                    key = key[7:].strip()
                value = value.strip()
                if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '\"'}:
                    value = value[1:-1]
                if key and value and key not in os.environ:
                    os.environ[key] = value
        except Exception:
            continue


# RowletAI uses the project-root .env for local API keys.
_journal_load_env_file()


def journal_secret(name):
    # Streamlit secrets remain supported, but .env is the normal local setup.
    try:
        value = st.secrets[name]
        if value is not None and str(value).strip():
            return str(value).strip()
    except Exception:
        pass
    value = os.getenv(name, "").strip()
    return value


