def journal_load_enrichment():
    """Load persistent IDX enrichment without touching core Sectors data."""
    try:
        if ENRICHMENT_FILE.exists():
            payload=json.loads(ENRICHMENT_FILE.read_text(encoding="utf-8"))
            return payload if isinstance(payload, dict) else {}
    except Exception:
        pass
    return {}


def journal_save_enrichment(payload):
    try:
        DATA.mkdir(parents=True, exist_ok=True)
        tmp=ENRICHMENT_FILE.with_suffix(".tmp")
        tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(ENRICHMENT_FILE)
    except Exception:
        pass


@st.cache_data(ttl=86400, show_spinner=False)
def journal_idx_profile(symbol):
    """Fetch one listed-company profile from IDX's public profile endpoint.

    This is metadata enrichment only. Financial metrics and scoring continue to
    come from the Sectors datasets. If IDX is unavailable, return an empty
    result and leave the original Sectors values untouched.
    """
    sym=str(symbol or "").upper().strip().replace(".JK", "")
    if not sym:
        return {}
    urls=[
        f"https://www.idx.co.id/primary/ListedCompany/GetCompanyProfiles?start=0&length=5&code={quote(sym)}",
        f"https://www.idx.co.id/umbraco/Surface/ListedCompany/GetCompanyProfiles?draw=1&start=0&length=5&search[value]={quote(sym)}&search[regex]=false",
    ]
    headers={
        "User-Agent":"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/142 Safari/537.36",
        "Accept":"application/json,text/plain,*/*",
        "Referer":"https://www.idx.co.id/en/listed-companies/company-profiles/",
    }
    for url in urls:
        try:
            req=Request(url,headers=headers)
            with urlopen(req,timeout=6) as response:
                raw=response.read().decode("utf-8",errors="ignore")
            payload=json.loads(raw)
            rows=payload.get("data") if isinstance(payload,dict) else None
            if not isinstance(rows,list):
                continue
            for item in rows:
                code=str(item.get("KodeEmiten") or item.get("Code") or "").upper().strip()
                if code == sym:
                    return {
                        "sector": str(item.get("Sektor") or item.get("Sector") or "").strip(),
                        "industry": str(item.get("Industri") or item.get("Industry") or "").strip(),
                        "subsector": str(item.get("SubSektor") or item.get("Subsector") or "").strip(),
                        "sub_industry": str(item.get("SubIndustri") or item.get("SubIndustry") or "").strip(),
                        "business": str(item.get("KegiatanUsahaUtama") or item.get("BusinessActivity") or "").strip(),
                        "website": str(item.get("Website") or "").strip(),
                        "source": "IDX",
                        "source_url": f"https://www.idx.co.id/en/listed-companies/company-profiles/{sym}",
                    }
        except Exception:
            continue
    return {}


def journal_resolve_context(row):
    """Resolve display context: Sectors first, IDX fallback second.

    The returned values are display/context fields only and are deliberately
    not fed into the Bagger Score or quantitative evidence calculations.
    """
    out=dict(row)
    symbol=str(out.get("symbol") or "").upper().strip()
    sector=str(out.get("sector") or "").strip()
    industry=str(out.get("industry") or "").strip()
    description=str(out.get("description") or "").strip()
    if sector and industry:
        out["context_source"]="Sectors API"
        return out

    cache=journal_load_enrichment()
    cached=cache.get(symbol) if isinstance(cache,dict) else None
    if not isinstance(cached,dict):
        cached=journal_idx_profile(symbol)
        if cached:
            cache[symbol]=cached
            journal_save_enrichment(cache)

    if cached:
        if not sector:
            out["sector"]=cached.get("sector") or ""
        if not industry:
            out["industry"]=cached.get("industry") or cached.get("sub_industry") or cached.get("subsector") or ""
        if not description:
            out["description"]=cached.get("business") or ""
        out["context_source"]="IDX" if (out.get("sector") or out.get("industry")) else "Sectors API"
    else:
        out["context_source"]="Sectors API"
    return out


def journal_activity_query(row):
    symbol = str(row.get("symbol") or "").upper().strip()
    if symbol in JOURNAL_VISUAL_OVERRIDES:
        return JOURNAL_VISUAL_OVERRIDES[symbol]
    sector = str(row.get("sector") or "").strip()
    industry = str(row.get("industry") or "").strip()
    description = str(row.get("description") or "").strip()
    key = industry.lower().replace("&", "and")
    mapped = JOURNAL_ACTIVITY_MAP.get(key) or JOURNAL_ACTIVITY_MAP.get(sector.lower())
    if mapped:
        return mapped
    if industry:
        return f"{industry} industrial operations logistics infrastructure"
    if sector:
        return f"{sector} industrial operations logistics infrastructure"
    # Last-resort issuer-name resolver. This prevents companies with missing
    # sector/industry metadata from collapsing into the same generic image.
    name_map={
        "samcro": "textile manufacturing hook and loop tape webbing tape weaving dyeing factory",
        "hyosung": "textile manufacturing weaving industrial factory",
        "alumindo": "aluminium manufacturing metal factory industrial production",
        "adaro": "coal mining haul trucks excavator stockpile power plant",
        "mahaka": "media broadcasting publishing studio production",
        "wahana": "food processing factory distribution warehouse consumer goods",
        "autopedia": "automotive marketplace used cars vehicle dealership automotive service",
        "bumi resources": "coal mining excavator haul truck coal stockpile mining operation",
        "bumi": "coal mining excavator haul truck coal stockpile mining operation",
    }
    company = str(row.get("company_name") or "").strip().lower()
    for token, mapped_name in name_map.items():
        if token in company:
            return mapped_name
    return description[:90] if description else "industrial business operations logistics"


def journal_visual_terms(row, symbol):
    """Build compact positive/negative terms for image relevance scoring."""
    query = journal_activity_query(row)
    company = str(row.get("company_name") or "").lower()
    sector = str(row.get("sector") or "").lower()
    industry = str(row.get("industry") or "").lower()
    raw = " ".join([query, company, sector, industry])
    tokens = [t for t in re.findall(r"[a-z0-9]+", raw) if len(t) >= 4]
    stop = {"company", "limited", "tbk", "tahap", "indonesia", "indonesian", "industry", "business", "operations", "industrial"}
    positive=[]
    for t in tokens:
        if t not in stop and t not in positive:
            positive.append(t)
    negative=["portrait", "wedding", "restaurant", "fashion", "abstract", "selfie", "meeting", "office desk"]
    return positive[:18], negative


@st.cache_data(ttl=86400, show_spinner=False)
def _journal_visual_terms(query):
    """Normalize query words used by all visual providers."""
    terms=[t for t in re.findall(r"[a-z0-9]+", str(query or "").lower()) if len(t)>=4]
    stop={"company","limited","tbk","tahap","indonesia","indonesian","industry","business","operations","industrial","services","development"}
    out=[]
    for t in terms:
        if t not in stop and t not in out:
            out.append(t)
    return out[:22]


def _journal_visual_score(text, positive, width=0, height=0, provider=""):
    """Score provider metadata only; no pixel/image inference is used."""
    text=str(text or "").lower()
    score=0
    for term in positive:
        if term in text:
            score += 6
    negative=("portrait","wedding","fashion","selfie","abstract","food","restaurant","party","vacation","beach")
    for term in negative:
        if term in text:
            score -= 10
    operational=("truck","excavator","mine","mining","coal","factory","warehouse","plant","port","ship","container","machinery","industrial","power","energy","infrastructure","logistics","transport","server","hospital","bank","building")
    for term in operational:
        if term in text:
            score += 3
    try:
        ratio=float(width)/float(height) if float(height)>0 else 0
        if ratio >= 1.45: score += 5
        elif ratio >= 1.25: score += 2
        elif ratio < 1.0: score -= 5
    except Exception:
        pass
    # Small provider-specific tie-breakers are deliberately modest; relevance
    # remains the dominant signal.
    if provider == "Unsplash": score += 1
    return score


@st.cache_data(ttl=3600, show_spinner=False)
def _journal_unsplash_visual(query, api_key, symbol=""):
    if not api_key or not query:
        return None
    try:
        params=urlencode({
            "query":query,
            "page":1,
            "per_page":20,
            "order_by":"relevant",
            "orientation":"landscape",
            "content_filter":"high",
        })
        url="https://api.unsplash.com/search/photos?"+params
        req=Request(url,headers={"Authorization":f"Client-ID {api_key}","Accept-Version":"v1","User-Agent":"RowletAI/2.0"})
        with urlopen(req,timeout=8) as response:
            payload=json.loads(response.read().decode("utf-8"))
        photos=payload.get("results") or []
        if not photos:
            return None
        positive=_journal_visual_terms(query)
        scored=[]
        for photo in photos:
            user=photo.get("user") or {}
            tags=photo.get("tags") or []
            tag_text=" ".join(str(x.get("title") or x.get("type") or "") for x in tags if isinstance(x,dict))
            text=" ".join([
                str(photo.get("alt_description") or ""),
                str(photo.get("description") or ""),
                str(user.get("name") or ""),
                tag_text,
            ])
            score=_journal_visual_score(text,positive,photo.get("width",0),photo.get("height",0),"Unsplash")
            scored.append((score,photo))
        best=max(x[0] for x in scored)
        finalists=[x[1] for x in scored if x[0]>=best-4]
        seed=sum(ord(c) for c in str(symbol or query))
        photo=finalists[seed % len(finalists)]
        urls=photo.get("urls") or {}
        links=photo.get("links") or {}
        user=photo.get("user") or {}
        profile=(user.get("links") or {}).get("html") or "https://unsplash.com/"
        image_url=urls.get("full") or urls.get("regular") or urls.get("small")
        if not image_url:
            return None
        return {
            "image_url":image_url,
            "photo_url":links.get("html") or "https://unsplash.com/",
            "photographer":user.get("name") or "Unsplash photographer",
            "photographer_url":profile,
            "provider":"Unsplash",
            "alt":photo.get("alt_description") or photo.get("description") or "",
            "score":best,
        }
    except Exception as exc:
        try:
            st.session_state["journal_visual_last_error"] = f"Unsplash: {type(exc).__name__}: {exc}"
        except Exception:
            pass
        return None


@st.cache_data(ttl=3600, show_spinner=False)
def journal_pexels_visual(query, api_key, symbol=""):
    """Pexels visual resolver; retry missing results after one hour."""
    if not api_key or not query:
        return None
    try:
        params=urlencode({"query":query,"per_page":24,"orientation":"landscape","size":"large","locale":"en-US"})
        url="https://api.pexels.com/v1/search?"+params
        req=Request(url,headers={"Authorization":api_key,"User-Agent":"RowletAI/2.0"})
        with urlopen(req,timeout=8) as response:
            payload=json.loads(response.read().decode("utf-8"))
        photos=payload.get("photos") or []
        if not photos:
            return None
        positive=_journal_visual_terms(query)
        scored=[]
        for photo in photos:
            text=" ".join([str(photo.get("alt") or ""),str(photo.get("url") or ""),str(photo.get("photographer") or "")])
            score=_journal_visual_score(text,positive,photo.get("width",0),photo.get("height",0),"Pexels")
            scored.append((score,photo))
        best=max(x[0] for x in scored)
        finalists=[x[1] for x in scored if x[0]>=best-4]
        seed=sum(ord(c) for c in str(symbol or query))
        photo=finalists[seed % len(finalists)]
        src=photo.get("src") or {}
        image_url=src.get("large2x") or src.get("large") or src.get("original")
        if not image_url:
            return None
        return {
            "image_url":image_url,
            "photo_url":photo.get("url") or "https://www.pexels.com/",
            "photographer":photo.get("photographer") or "Pexels photographer",
            "photographer_url":photo.get("photographer_url") or "https://www.pexels.com/",
            "provider":"Pexels",
            "alt":photo.get("alt") or "",
            "score":best,
        }
    except Exception:
        return None


@st.cache_data(ttl=3600, show_spinner=False)
def _journal_pixabay_visual(query, api_key, symbol=""):
    """Search Pixabay and download the selected image before displaying it.

    Pixabay's current API documentation says returned image URLs may be used
    temporarily for search display, but permanent hotlinking is not allowed;
    therefore the selected image is downloaded and embedded as a data URL.
    """
    if not api_key or not query:
        return None
    try:
        params=urlencode({
            "key":api_key,
            "q":query[:100],
            "lang":"en",
            "image_type":"photo",
            "orientation":"horizontal",
            "category":"industry",
            "min_width":1000,
            "min_height":600,
            "safesearch":"true",
            "order":"popular",
            "page":1,
            "per_page":30,
        })
        url="https://pixabay.com/api/?"+params
        req=Request(url,headers={"User-Agent":"RowletAI/2.0"})
        with urlopen(req,timeout=8) as response:
            payload=json.loads(response.read().decode("utf-8"))
        hits=payload.get("hits") or []
        if not hits:
            # Category=industry can be too restrictive for some sectors.
            params=urlencode({"key":api_key,"q":query[:100],"lang":"en","image_type":"photo","orientation":"horizontal","min_width":1000,"min_height":600,"safesearch":"true","order":"popular","page":1,"per_page":30})
            req=Request("https://pixabay.com/api/?"+params,headers={"User-Agent":"RowletAI/2.0"})
            with urlopen(req,timeout=8) as response:
                payload=json.loads(response.read().decode("utf-8"))
            hits=payload.get("hits") or []
        if not hits:
            return None
        positive=_journal_visual_terms(query)
        scored=[]
        for hit in hits:
            text=" ".join([str(hit.get("tags") or ""),str(hit.get("pageURL") or "")])
            score=_journal_visual_score(text,positive,hit.get("imageWidth",0),hit.get("imageHeight",0),"Pixabay")
            score += min(float(hit.get("likes") or 0)/100.0,5.0)
            scored.append((score,hit))
        best=max(x[0] for x in scored)
        finalists=[x[1] for x in scored if x[0]>=best-4]
        seed=sum(ord(c) for c in str(symbol or query))
        hit=finalists[seed % len(finalists)]
        image_url=hit.get("fullHDURL") or hit.get("largeImageURL") or hit.get("webformatURL")
        if not image_url:
            return None
        req=Request(image_url,headers={"User-Agent":"RowletAI/2.0"})
        with urlopen(req,timeout=12) as response:
            raw=response.read()
            content_type=response.headers.get_content_type() or "image/jpeg"
        import base64
        data_url="data:%s;base64,%s"%(content_type,base64.b64encode(raw).decode("ascii"))
        return {
            "image_url":data_url,
            "photo_url":hit.get("pageURL") or "https://pixabay.com/",
            "photographer":hit.get("user") or "Pixabay contributor",
            "photographer_url":f'https://pixabay.com/users/{quote(str(hit.get("user") or ""),safe="")}-{hit.get("user_id")}/' if hit.get("user_id") else "https://pixabay.com/",
            "provider":"Pixabay",
            "alt":hit.get("tags") or "",
            "score":best,
        }
    except Exception:
        return None



# Company logo domain overrides used by Logo.dev.
LOGO_DOMAIN_OVERRIDES = {
    "AADI.JK": "adaroindonesia.com",
    "ABMM.JK": "abm-investama.com",
    "ALMI.JK": "alumindo.com",
    "COCO.JK": "wahanaintifood.com",
}

def journal_logo_url(symbol):
    token = journal_secret("LOGO_DEV_TOKEN")
    if not token:
        # Logo.dev publishable token may also be supplied through the existing
        # application environment.  Never fabricate a secret here.
        return ""
    sym = str(symbol or "").upper().strip()
    domain = LOGO_DOMAIN_OVERRIDES.get(sym)
    token_q = quote(token, safe="")
    if domain:
        return (
            f"https://img.logo.dev/{domain}?token={token_q}"
            "&size=160&format=png&theme=light&retina=true"
        )
    ticker = quote(sym, safe="")
    return (
        f"https://img.logo.dev/ticker/{ticker}?token={token_q}"
        "&size=160&format=png&theme=light&retina=true"
    )


@st.cache_data(ttl=3600, show_spinner=False)
def _journal_image_url_allowed(image_url):
    """Allow server-side image fetches only from the providers used by the app."""
    try:
        parts=urlsplit(str(image_url or '').strip())
        host=(parts.hostname or '').lower().rstrip('.')
        trusted=('images.unsplash.com','images.pexels.com','cdn.pixabay.com')
        return parts.scheme.lower()=='https' and any(host==domain or host.endswith('.'+domain) for domain in trusted)
    except Exception:
        return False


def _journal_embed_remote_image(image_url, provider=""):
    """Fetch a bounded image from an approved provider and reject unsafe redirects."""
    if not image_url:
        return ""
    if str(image_url).startswith("data:image/"):
        return str(image_url)
    if not _journal_image_url_allowed(image_url):
        return ""
    try:
        from urllib.request import HTTPRedirectHandler, build_opener
        class _TrustedImageRedirect(HTTPRedirectHandler):
            def redirect_request(self, req, fp, code, msg, headers, newurl):
                if not _journal_image_url_allowed(newurl):
                    return None
                return super().redirect_request(req,fp,code,msg,headers,newurl)
        req=Request(str(image_url),headers={"User-Agent":"RowletAI/2.0","Accept":"image/avif,image/webp,image/jpeg,image/png,image/*;q=0.8"})
        opener=build_opener(_TrustedImageRedirect())
        with opener.open(req,timeout=12) as response:
            if not _journal_image_url_allowed(response.geturl()):
                return ""
            content_type=(response.headers.get_content_type() or "").lower()
            content_length=response.headers.get('Content-Length')
            if content_length and int(content_length)>8_000_000:
                return ""
            raw=response.read(8_000_001)
        if not raw or len(raw)>8_000_000:
            return ""
        if content_type not in {"image/jpeg","image/png","image/webp","image/gif","image/avif"}:
            return ""
        import base64
        return "data:%s;base64,%s" % (content_type,base64.b64encode(raw).decode("ascii"))
    except Exception:
        return ""



# Last-resort visual references. These are only used when all configured API
# providers fail or no API key is available. API-selected images always win.
# The references are free-to-use Unsplash photos and are deliberately generic
# by industry so the Journal never collapses to a blank hero.
