# IDX/Sectors data can use slightly different labels. Normalize them before
# looking up a fallback so labels such as "Properties & Real Estate" do not
# accidentally bypass the fallback engine.
def _journal_normalize_visual_sector(value):
    text = str(value or "").strip().lower()
    text = text.replace("&", "and")
    text = re.sub(r"[^a-z0-9]+", " ", text).strip()
    aliases = {
        "properties and real estate": "real estate",
        "property and real estate": "real estate",
        "real estate": "real estate",
        "consumer cyclical": "consumer cyclicals",
        "consumer defensive": "consumer defensive",
        "communication services": "communication services",
        "telecommunications": "communication services",
        "telecommunication": "communication services",
        "basic material": "basic materials",
        "financial": "financials",
        "banks": "financials",
        "banking": "financials",
    }
    return aliases.get(text, text)

def _journal_static_fallback(row, symbol):
    sym = str(symbol or row.get("symbol") or "").upper().strip()
    item = JOURNAL_STATIC_VISUAL_FALLBACKS.get(sym)
    if item:
        return dict(item)

    # Prefer industry-specific sector fallbacks.
    sector = _journal_normalize_visual_sector(row.get("sector"))
    item = JOURNAL_SECTOR_STATIC_FALLBACKS.get(sector)
    if item:
        return dict(item)

    # If sector is missing, use the normalized industry as a routing hint.
    industry = _journal_normalize_visual_sector(row.get("industry"))
    for key, mapped in {
        "media": "communication services",
        "telecommunications": "communication services",
        "bank": "financials",
        "banking": "financials",
        "hospital": "healthcare",
        "medical": "healthcare",
        "software": "technology",
        "data center": "technology",
        "technology": "technology",
        "mining": "basic materials",
        "coal": "energy",
        "oil": "energy",
        "gas": "energy",
        "property": "real estate",
        "real estate": "real estate",
        "construction": "real estate",
        "retail": "consumer cyclicals",
        "food": "consumer defensive",
        "beverage": "consumer defensive",
        "logistics": "transportation",
        "transport": "transportation",
    }.items():
        if key in industry:
            item = JOURNAL_SECTOR_STATIC_FALLBACKS.get(mapped)
            if item:
                return dict(item)

    # Absolute last resort: never return an empty hero.
    return dict(JOURNAL_SECTOR_STATIC_FALLBACKS["technology"])

def _journal_visual_query_variants(row):
    """Generate progressively broader search queries for the three providers."""
    symbol = str(row.get("symbol") or "").upper().strip()
    primary = journal_activity_query(row).strip()
    sector = str(row.get("sector") or "").strip()
    industry = str(row.get("industry") or "").strip()
    variants=[]
    for q in [
        primary,
        f"{industry} {sector} business operations" if industry and sector else "",
        f"{sector} business operations infrastructure" if sector else "",
        "corporate business operations infrastructure",
    ]:
        q=" ".join(str(q).split())
        if q and q not in variants:
            variants.append(q[:100])
    # Keep at most four calls per provider; this is enough to recover from
    # overly-specific queries without causing an uncontrolled API loop.
    return variants[:4]


def journal_business_visual(row, symbol):
    """Multi-source visual engine with query fallbacks and a guaranteed image fallback.

    Resolution order:
      1. Unsplash, Pexels and Pixabay are queried independently.
      2. Each provider receives progressively broader search terms.
      3. The strongest usable API result wins.
      4. If all providers fail, an industry-routed static Unsplash reference is used.

    This means a missing provider result can never produce a blank Company Header.
    """
    sym=str(symbol or row.get("symbol") or "").upper().strip()
    queries=_journal_visual_query_variants(row)
    primary_query=queries[0] if queries else journal_activity_query(row)
    unsplash_key=(journal_secret("UNSPLASH_ACCESS_KEY") or journal_secret("UNSPLASH_API_KEY") or journal_secret("UNSPLASH_KEY") or journal_secret("UNSPLASH_ACCESS_TOKEN"))
    pexels_key=(journal_secret("PEXELS_API_KEY") or journal_secret("PEXELS_TOKEN") or journal_secret("PEXELS_KEY") or journal_secret("PEXELS_ACCESS_KEY"))
    pixabay_key=(journal_secret("PIXABAY_API_KEY") or journal_secret("PIXABAY_KEY") or journal_secret("PIXABAY_TOKEN") or journal_secret("PIXABAY_ACCESS_KEY"))

    candidates=[]
    status=[]

    def collect(provider_name, enabled, resolver):
        if not enabled:
            status.append(f"{provider_name}: key missing")
            return
        found=None
        used_query=""
        for q in queries:
            item=resolver(q)
            if item:
                found=item
                used_query=q
                break
        if found:
            found=dict(found)
            found["search_query"]=used_query
            candidates.append(found)
            status.append(f"{provider_name}: OK ({used_query[:42]})")
        else:
            status.append(f"{provider_name}: no usable result")

    collect("Unsplash", unsplash_key, lambda q: _journal_unsplash_visual(q,unsplash_key,sym))
    collect("Pexels", pexels_key, lambda q: journal_pexels_visual(q,pexels_key,sym))
    collect("Pixabay", pixabay_key, lambda q: _journal_pixabay_visual(q,pixabay_key,sym))

    # Highest relevance first; provider order is only a stable tie-breaker.
    if candidates:
        order={"Unsplash":0,"Pexels":1,"Pixabay":2}
        candidates.sort(key=lambda x:(-float(x.get("score",0)),order.get(x.get("provider"),9)))
        photo=candidates[0]
        selected=photo.get("provider","")
        fallback=False
    else:
        photo=_journal_static_fallback(row, sym)
        selected=photo.get("provider","")
        fallback=True

    # Try to embed API images server-side. If the selected API image cannot be
    # fetched by the Streamlit runtime, immediately switch to the guaranteed
    # static fallback rather than leaving a broken/blank hero.
    if photo.get("image_url") and not str(photo.get("image_url")).startswith("data:image/"):
        embedded=_journal_embed_remote_image(photo.get("image_url"), photo.get("provider",""))
        if embedded:
            photo=dict(photo)
            photo["image_url"]=embedded
        elif not fallback:
            fallback_photo=_journal_static_fallback(row, sym)
            if fallback_photo:
                photo=fallback_photo
                selected=photo.get("provider","")
                fallback=True
                status.append("API image fetch failed → static fallback used")

    try:
        st.session_state["journal_visual_status"]={
            "symbol":sym,
            "query":primary_query,
            "query_variants":queries,
            "status":status,
            "selected":selected,
            "fallback":fallback,
        }
    except Exception:
        pass

    return {
        "photo":photo,
        "logo_url":journal_logo_url(sym),
        "query":primary_query,
        "sources_checked":[x for x,k in (("Unsplash",unsplash_key),("Pexels",pexels_key),("Pixabay",pixabay_key)) if k],
        "status":status,
    }

@st.cache_data(ttl=900, show_spinner=False)
def journal_live_price(symbol):
    """Resolve a latest displayed share price when the local daily cache is incomplete."""
    sym=str(symbol or "").upper().strip()
    if not sym:
        return None
    api_symbol=sym[:-3] if sym.endswith('.JK') else sym
    sectors_token=(journal_secret("SECTORS_API_KEY") or journal_secret("SECTORS_API_TOKEN") or journal_secret("SECTORS_TOKEN") or journal_secret("SECTORS_API"))
    if sectors_token:
        try:
            url=f"https://api.sectors.app/v2/daily/{quote(api_symbol, safe='')}/"
            headers_list=[
                {"Authorization":f"Bearer {sectors_token}","User-Agent":"RowletAI/2.0"},
                {"Authorization":str(sectors_token),"User-Agent":"RowletAI/2.0"},
                {"X-API-Key":str(sectors_token),"User-Agent":"RowletAI/2.0"},
            ]
            for headers in headers_list:
                try:
                    req=Request(url,headers=headers)
                    with urlopen(req,timeout=6) as response:
                        payload=json.loads(response.read().decode("utf-8"))
                    rows=payload.get("data") if isinstance(payload,dict) else payload
                    if isinstance(rows,dict): rows=list(rows.values())
                    if isinstance(rows,list):
                        for item in reversed(rows):
                            if not isinstance(item,dict): continue
                            for key in ("close","price","last","last_price"):
                                value=n(item.get(key))
                                if not np.isnan(value) and value>0: return float(value)
                except Exception:
                    continue
        except Exception:
            pass
    try:
        url=("https://query1.finance.yahoo.com/v8/finance/chart/"+quote(sym,safe="")+"?range=5d&interval=1d")
        req=Request(url,headers={"User-Agent":"Mozilla/5.0 RowletAI/2.0"})
        with urlopen(req,timeout=6) as response:
            payload=json.loads(response.read().decode("utf-8"))
        result=((payload.get("chart") or {}).get("result") or [None])[0]
        if result:
            meta=result.get("meta") or {}
            for key in ("regularMarketPrice","previousClose"):
                value=n(meta.get(key))
                if not np.isnan(value) and value>0: return float(value)
            closes=(((result.get("indicators") or {}).get("quote") or [{}])[0].get("close") or [])
            for value in reversed(closes):
                value=n(value)
                if not np.isnan(value) and value>0: return float(value)
    except Exception:
        pass
    return None


def journal_visual_fallback(symbol, query):
    """Return a clean neutral hero background when no photo provider is available.

    Do not synthesize pseudo-photographic business scenes. A wrong visual is more
    misleading than a clean research-terminal background. Real business imagery
    is supplied only by the configured Pexels provider.
    """
    return ""

def journal_empty_chart(title, message, height=250):
    fig=go.Figure()
    fig.update_layout(
        height=height,
        margin=dict(l=8,r=8,t=28,b=8),
        paper_bgcolor='rgba(0,0,0,0)',
        plot_bgcolor='rgba(247,250,253,.75)',
        xaxis=dict(visible=False), yaxis=dict(visible=False),
        annotations=[dict(text=f'<b>{title}</b><br><span style="font-size:11px">{message}</span>',
                           x=.5,y=.5,xref='paper',yref='paper',showarrow=False,
                           font=dict(size=13,color='#70869a'),align='center')],
        shapes=[dict(type='rect',xref='paper',yref='paper',x0=.01,y0=.02,x1=.99,y1=.98,
                     line=dict(color='#dce6ee',width=1,dash='dot'),fillcolor='rgba(255,255,255,.15)')]
    )
    return fig


def journal_activity_tags(row):
    symbol=str(row.get("symbol") or "").upper()
    industry=str(row.get("industry") or "").lower()
    sector=str(row.get("sector") or "").lower()
    company=str(row.get("company_name") or "").lower()
    issuer_overrides={
        "AADI.JK":["Coal Mining","Mining Services","Logistics & Transportation","Energy","Infrastructure"],
        "ACRO.JK":["Hook & Loop","Webbing Tape","Textile Manufacturing","Industrial Products","Distribution"],
    }
    if symbol in issuer_overrides:
        return issuer_overrides[symbol]
    if "adaro" in company:
        return ["Coal Mining", "Mining Services", "Logistics & Transportation", "Energy", "Infrastructure"]
    presets={
        "banks":["Commercial Banking","Corporate Banking","Consumer Banking","Digital Banking"],
        "oil, gas & coal":["Energy Production","Mining","Logistics","Energy Development"],
        "transportation":["Transportation","Logistics","Fleet Services","Infrastructure"],
        "technology":["Technology","Digital Services","Software","Data Infrastructure"],
        "telecommunications":["Telecommunications","Digital Infrastructure","Connectivity","Data Services"],
        "healthcare":["Healthcare Services","Medical Services","Hospitals","Healthcare Infrastructure"]
    }
    for key,tags in presets.items():
        if key in industry or key in sector:
            return tags
    if industry:
        return [industry.title(),"Operations","Services","Infrastructure"]
    if sector:
        return [sector.title(),"Operations","Services","Infrastructure"]
    return ["Core Operations","Products","Services","Infrastructure"]


def journal_activity_icon(label):
    """Return a crisp, transparent SVG icon; no emoji or raster asset is used."""
    key=str(label or "").lower()
    if "coal" in key or "mining" in key:
        body='<path d="M6 16.5 11.5 8l4 3.5L21 5"/><path d="m4 19 5-5 3 3 5-5"/>'
    elif "logistics" in key or "transport" in key or "port" in key:
        body='<rect x="4" y="9" width="11" height="7" rx="1.5"/><path d="M15 11h3l3 3v2h-6z"/><circle cx="8" cy="18" r="1.7"/><circle cx="18" cy="18" r="1.7"/>'
    elif "energy" in key or "power" in key:
        body='<path d="M13.5 2 5 13h6l-1 9 8.5-12h-6z"/>'
    elif "infrastructure" in key:
        body='<path d="M4 20h16M6 20V9l6-5 6 5v11M9 20v-6h6v6M4 9h16"/>'
    elif "bank" in key or "finance" in key:
        body='<path d="m4 9 8-5 8 5M5 10h14M7 10v7m5-7v7m5-7v7M4 19h16"/>'
    elif "technology" in key or "digital" in key or "software" in key:
        body='<rect x="4" y="5" width="16" height="11" rx="2"/><path d="M8 20h8M12 16v4M8 9h8M8 12h5"/>'
    elif "health" in key or "medical" in key:
        body='<path d="M12 20s-7-4.3-7-10a4 4 0 0 1 7-2 4 4 0 0 1 7 2c0 5.7-7 10-7 10Z"/><path d="M12 8v6M9 11h6"/>'
    else:
        body='<circle cx="12" cy="12" r="8"/><path d="M12 8v4l3 2"/>'
    return f'<svg class="rj01-business-icon-svg" viewBox="0 0 24 24" aria-hidden="true" focusable="false">{body}</svg>'


