    growth_score=n(row.get('growth_score')); quality_score=n(row.get('quality_score')); div_yield=n(row.get('yield_ttm')); valuation_score=n(row.get('valuation_score')); risk_score=n(row.get('risk_score')); momentum_score=n(row.get('momentum_score'))
    ret20=n(row.get('return_20d')); ret60=n(row.get('return_60d')); rev_growth=n(row.get('yoy_quarter_revenue_growth')); earn_growth=n(row.get('yoy_quarter_earnings_growth'))
    cov_n,cov_t,_=journal_coverage(row)
    score_specs=[('Growth','growth','growth_score','▥'),('Quality','quality','quality_score','◉'),('Valuation','valuation','valuation_score','◆'),('Risk','risk','risk_score','⬟'),('Momentum','momentum','momentum_score','▥')]
    score_values={
        'growth':growth_score,'growth_score':growth_score,
        'quality':quality_score,'quality_score':quality_score,
        'valuation':valuation_score,'valuation_score':valuation_score,
        'risk':risk_score,'risk_score':risk_score,
        'momentum':momentum_score,'momentum_score':momentum_score,
    }
    score_bars={
        'growth':growth_score,'growth_score':growth_score,
        'quality':quality_score,'quality_score':quality_score,
        'valuation':valuation_score,'valuation_score':valuation_score,
        'risk':risk_score,'risk_score':risk_score,
        'momentum':momentum_score,'momentum_score':momentum_score,
    }
    def _growth_band(x):
        if not np.isfinite(x): return 'Unavailable'
        return 'Strong' if x>=.25 else ('Positive' if x>=.05 else ('Stable' if x>=-.05 else 'Negative'))
    _rev_band=_growth_band(rev_growth); _earn_band=_growth_band(earn_growth)
    if _rev_band=='Strong' and _earn_band=='Strong':
        _growth_summary='Strong growth evidence is visible across revenue and earnings.'
    elif _rev_band in ('Positive','Strong') and _earn_band in ('Positive','Strong'):
        _growth_summary='Positive growth evidence is visible across revenue and earnings.'
    elif _rev_band=='Negative' or _earn_band=='Negative':
        _growth_summary='Growth evidence is mixed, with at least one negative measured growth input.'
    elif _rev_band=='Unavailable' and _earn_band=='Unavailable':
        _growth_summary='Growth evidence is currently unavailable.'
    else:
        _growth_summary=f'Growth evidence is mixed across revenue ({_rev_band.lower()}) and earnings ({_earn_band.lower()}).'
    summaries={
      'growth': _growth_summary,
      'quality': ('Quality evidence is measured through the canonical Bagger Quality Score.' if np.isfinite(quality_score) else 'Quality evidence is currently unavailable.'),
      'valuation': ('Valuation evidence is available through the current Journal valuation layer.' if np.isfinite(valuation_score) else 'Valuation evidence is currently unavailable.'),
      'risk': ('Elevated volatility is visible, while drawdown and daily-loss evidence remain measurable.' if ((np.isfinite(n(row.get('volatility_20d'))) and n(row.get('volatility_20d'))>=.35) or (np.isfinite(n(row.get('volatility_60d'))) and n(row.get('volatility_60d'))>=.35)) else 'Risk evidence is measured across volatility, drawdown and daily-loss inputs.'),
      'momentum': ('Momentum is positive across both 20D and 60D horizons.' if np.isfinite(ret20) and np.isfinite(ret60) and ret20>0 and ret60>0 else 'Momentum evidence is measured across the available 20D and 60D horizons.')
    }
    bullets={
      'growth':[f'Revenue growth {journal_pct(rev_growth)}' if np.isfinite(rev_growth) else 'Revenue growth evidence available',f'Earnings growth {journal_pct(earn_growth)}' if np.isfinite(earn_growth) else 'Earnings growth evidence available','Measured growth trend'],
      'quality':[f'Quality score {quality_score:.1f}/100' if np.isfinite(quality_score) else 'Quality score unavailable',f'ROE {journal_pct(row.get("roe_ttm"))}' if np.isfinite(n(row.get('roe_ttm'))) else 'ROE evidence unavailable',f'ROA {journal_pct(row.get("roa_ttm"))}' if np.isfinite(n(row.get('roa_ttm'))) else 'ROA evidence unavailable'],
      'valuation':['Trading valuation evidence is measured','Supported by available valuation inputs','Scenario outputs remain separate from measured signals'],
      'risk':['High short-term volatility' if np.isfinite(n(row.get('volatility_20d'))) and n(row.get('volatility_20d'))>=.35 else 'Measured short-term volatility',f'Max drawdown {journal_pct(row.get("max_drawdown_60d"))}' if np.isfinite(n(row.get('max_drawdown_60d'))) else 'Drawdown evidence unavailable','Daily-loss evidence is measurable'],
      'momentum':[f'20D momentum: {journal_pct(ret20)}' if np.isfinite(ret20) else '20D momentum unavailable',f'60D momentum: {journal_pct(ret60)}' if np.isfinite(ret60) else '60D momentum unavailable','Measured momentum trend']
    }
    cards_html=[]
    for label,css,key,icon in score_specs:
        raw=score_values.get(key, np.nan); bar=score_bars.get(key, np.nan)
