    page_key = str(st.query_params.get("page", "home")).lower()
    # FINAL ROWLETAI NAVIGATION — locked order
    # Home → Market Intelligence → Company Journal → Compare Insight → Methodology
    # Radar is intentionally removed from the visible navigation.
    page_map = {
        "home": "⌂  Home",
        "market": "◈  Market Intelligence",
        "journal": "▤  Company Journal",
        "compare": "⚖  Compare Insight",
        "methodology": "⚙  Methodology",
    }

    nav_html = []
    for key, label, icon in [
        ("home", "Home", "nav_home.png"),
        ("market", "Market Intelligence", "nav_market.png"),
        ("journal", "Company Journal", "nav_journal.png"),
        ("compare", "Compare Insight", "nav_compare.png"),
        ("methodology", "Methodology", "nav_methodology.png"),
    ]:
        active = "active" if page_key == key else ""
        nav_html.append(
            f'<a class="rowlet-nav-item {active}" href="?page={key}">'
            f'<img class="rowlet-nav-img" src="{sidebar_asset_uri(icon)}" alt="">'
            f'<span class="rowlet-nav-label">{label}</span></a>'
        )

    st.html('<div class="rowlet-nav-wrap">' + "".join(nav_html) + '</div>')
    page = page_map.get(page_key, "⌂  Home")

    st.divider()

    # --------------------------------------------------------
    # HACKATHON CARD
    # Market Overview intentionally removed from the sidebar.
    # Market statistics belong inside Market Intelligence.
    # --------------------------------------------------------
    st.html(
        f"""
        <div class="gio-hack">
            <div class="gio-hack-icon"><img src="{hack_uri}"></div>
            <div style="flex:1;">
                <div class="gio-hack-title">
                    Built for<br>Sectors Hackathon
                </div>
            </div>
            <div style="
                color:#1769df;
                font-size:15px;
                align-self:flex-start;
            ">↗</div>
        </div>
        """
    )



