st.markdown('<style id="growth-forecast-v35-redesign">\n.j-growth-v35-header{min-height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 4px;}\n.j-growth-v35-heading{display:flex;align-items:center;gap:12px;}\n.j-growth-v35-icon{width:38px;height:38px;border-radius:11px;background:#eaf3ff;border:1px solid #cfe3f8;display:inline-flex;align-items:center;justify-content:center;color:#1769ff;box-shadow:0 5px 14px rgba(23,105,255,.10);}\n.j-growth-v35-icon svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;}\n.j-growth-v35-title{font-size:18px;font-weight:900;color:#12385f;line-height:1.15;}.j-growth-v35-sub{font-size:10px;color:#7a91a8;margin-top:4px;}\n.j-growth-chart-heading{display:flex;justify-content:space-between;align-items:center;padding:2px 2px 6px;}.j-growth-chart-kicker{font-size:12px;font-weight:900;color:#183f63;display:block;}.j-growth-chart-caption{font-size:9px;color:#7890a6;display:block;margin-top:3px;}.j-growth-chart-range{font-size:9px;font-weight:850;color:#4d6c86;background:#f3f8fd;border:1px solid #d6e4ef;border-radius:999px;padding:5px 8px;}\n.j-growth-takeaways{height:100%;min-height:350px;background:linear-gradient(180deg,#f4f9ff 0%,#fff 100%);border:1px solid #d7e5f1;border-radius:14px;padding:14px;box-sizing:border-box;box-shadow:0 5px 18px rgba(30,65,95,.045);}.j-growth-take-head{display:flex;align-items:center;gap:8px;font-size:15px;font-weight:900;color:#173e61;margin-bottom:10px;}.j-growth-take-item{display:flex;gap:9px;padding:10px 0;border-top:1px solid #e7eef4;align-items:flex-start;}.j-growth-take-item:first-of-type{border-top:0;}.j-growth-take-item b{font-size:10.5px;color:#173e61;display:block;}.j-growth-take-item p{font-size:9.5px;color:#617c93;line-height:1.45;margin:3px 0 0;}\n.j-take-icon{width:28px;height:28px;min-width:28px;border-radius:9px;display:inline-flex;align-items:center;justify-content:center;}.j-take-icon svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;}.j-take-icon.target{background:#eaf3ff;color:#1769ff;}.j-take-icon.green{background:#e8f8ef;color:#159447;}.j-take-icon.blue{background:#edf4ff;color:#2a72c7;}.j-take-icon.purple{background:#f2edff;color:#7357d8;}\n.j-scenario-grid-v35{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:12px;}.j-scenario-card-v35{border:1px solid #dbe5ed;border-radius:14px;padding:15px 16px;min-height:250px;box-sizing:border-box;box-shadow:0 5px 18px rgba(30,65,95,.035);position:relative;overflow:hidden;}.j-scenario-card-v35:after{content:"";position:absolute;right:18px;bottom:16px;width:58px;height:58px;opacity:.09;background:linear-gradient(180deg,currentColor 20%,transparent 20%,transparent 40%,currentColor 40%,currentColor 60%,transparent 60%,transparent 80%,currentColor 80%);border-radius:3px;}.j-scenario-card-v35.j-scenario-bear{background:linear-gradient(180deg,#fff4f4 0%,#fff 78%);border-color:#f0c7c9;color:#d9363e;}.j-scenario-card-v35.j-scenario-base{background:linear-gradient(180deg,#f3f8ff 0%,#fff 78%);border-color:#cbddef;color:#1769d1;}.j-scenario-card-v35.j-scenario-bull{background:linear-gradient(180deg,#eaf9f0 0%,#fff 78%);border-color:#b9dec8;color:#128a4a;}.j-scenario-v35-top{display:flex;align-items:center;gap:10px;position:relative;z-index:1;}.j-scenario-v35-icon{width:48px;height:48px;border-radius:12px;background:rgba(255,255,255,.82);border:1px solid currentColor;display:inline-flex;align-items:center;justify-content:center;box-shadow:0 4px 10px rgba(30,65,95,.05);}.j-scenario-v35-icon svg{width:31px;height:31px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;}.j-scenario-v35-head{min-width:0;}.j-scenario-v35-head .j-scenario-name{font-size:17px!important;font-weight:900!important;color:currentColor!important;}.j-scenario-v35-head .j-scenario-sub{font-size:12px!important;color:#6c8298!important;margin-top:3px;}.j-scenario-badge{margin-left:auto;font-size:9px;font-weight:900;padding:6px 9px;border-radius:999px;background:rgba(255,255,255,.7);border:1px solid currentColor;white-space:nowrap;}.j-scenario-v35-divider{height:1px;background:rgba(205,219,230,.8);margin:12px 0 3px;position:relative;z-index:1;}.j-scenario-card-v35 .j-scenario-metric{position:relative;z-index:1;padding:8px 0;font-size:12px!important;}.j-scenario-card-v35 .j-scenario-metric span{font-size:12px!important;color:#4e6981!important;}.j-scenario-card-v35 .j-scenario-metric b{font-size:14px!important;color:currentColor!important;}.j-scenario-card-v35 .j-scenario-assump-v35{position:relative;z-index:1;margin-top:7px;color:#526e84;font-size:10.5px;}.j-scenario-assump-v35 b{font-size:11px;color:#173e61;}.j-scenario-assump-v35 ul{margin:5px 0 0 17px;padding:0;line-height:1.55;}\n/* Clean blue segmented metric switcher */\n[data-testid="stRadio"] > div[role="radiogroup"]{display:flex!important;justify-content:flex-end!important;gap:6px!important;align-items:center!important;}[data-testid="stRadio"] > div[role="radiogroup"] > label{margin:0!important;padding:0!important;border:1px solid #d5e3ef!important;border-radius:10px!important;background:#f7fafd!important;min-height:38px!important;}[data-testid="stRadio"] > div[role="radiogroup"] > label > div:first-child{display:none!important;}[data-testid="stRadio"] > div[role="radiogroup"] > label > div:last-child{padding:0 13px!important;display:flex!important;align-items:center!important;min-height:38px!important;}[data-testid="stRadio"] > div[role="radiogroup"] p{font-size:12px!important;font-weight:850!important;color:#56708a!important;margin:0!important;white-space:nowrap!important;}[data-testid="stRadio"] > div[role="radiogroup"] > label:has(input:checked){background:#eaf4ff!important;border-color:#9fc9f5!important;box-shadow:0 3px 10px rgba(23,105,255,.08)!important;}[data-testid="stRadio"] > div[role="radiogroup"] > label:has(input:checked) p{color:#1565c0!important;}\n@media(max-width:1050px){.j-growth-v35-sub,.j-growth-chart-caption{display:none!important;}.j-growth-takeaways{min-height:320px!important;}.j-scenario-badge{display:none!important;}}@media(max-width:760px){.j-growth-v35-title{font-size:17px!important;}.j-growth-v35-header{min-height:50px!important;}.j-scenario-grid-v35{grid-template-columns:1fr!important;}.j-growth-takeaways{min-height:0!important;}.j-scenario-card-v35{min-height:220px!important;}.j-growth-chart-range{display:none!important;}}\n</style>', unsafe_allow_html=True)

